int binarySearch(vector<int>& arr, int target) {
    int l = 0;
    int r = arr.size() - 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target)
            l = mid + 1;
        else
            r = mid - 1;
    }
    return -1;
}

int lowerBound(vector<int>& arr, int target) {
    int l = 0;
    int r = arr.size();
    while (l < r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] < target)
            l = mid + 1;
        else
            r = mid;
    }
    return l;
}

int upperBound(vector<int>& arr, int target) {
    int l = 0;
    int r = arr.size();
    while (l < r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] <= target)
            l = mid + 1;
        else
            r = mid;
    }
    return l;
}

pair<int, int> firstLast(const vector<int>& arr, int target) {
    int n = static_cast<int>(arr.size());
    int l = 0;
    int r = n;
    while (l < r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] < target) {
            l = mid + 1;
        } else {
            r = mid;
        }
    }
    int first = l;
    if (first == n || arr[first] != target) return {-1, -1};

    l = first;
    r = n;
    while (l < r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] <= target) {
            l = mid + 1;
        } else {
            r = mid;
        }
    }
    return {first, l - 1};
}

