int searchRotated(vector<int>& arr, int target) {
    int l = 0;
    int r = arr.size() - 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] == target) return mid;
        // Left half is sorted
        if (arr[l] <= arr[mid]) {
            if (arr[l] <= target && target < arr[mid]) {
                r = mid - 1;
            } else {
                l = mid + 1;
            }
        }
        // Right half is sorted
        else {
            if (arr[mid] < target && target <= arr[r]) {
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
    }
    return -1;
}

bool searchRotatedDuplicates(vector<int>& arr, int target) {
    int l = 0;
    int r = arr.size() - 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] == target) return true;
        // Cannot determine sorted half
        if (arr[l] == arr[mid] && arr[mid] == arr[r]) {
            l++;
            r--;
            continue;
        }
        if (arr[l] <= arr[mid]) {
            if (arr[l] <= target && target < arr[mid])
                r = mid - 1;
            else
                l = mid + 1;
        } else {
            if (arr[mid] < target && target <= arr[r])
                l = mid + 1;
            else
                r = mid - 1;
        }
    }
    return false;
}

