}
int binarySearchDecreasing(vector<int>& arr, int l, int r, int target) {
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] > target)
            l = mid + 1;
        else
            r = mid - 1;
    }
