}

void countingSort(vector<int>& arr) {
    if (arr.empty()) return;
    int mn = *min_element(arr.begin(), arr.end());
    int mx = *max_element(arr.begin(), arr.end());
    vector<int> cnt(mx - mn + 1, 0);
    for (int x : arr) cnt[x - mn]++;
    int idx = 0;
    for (int i = 0; i < cnt.size(); i++) {
        while (cnt[i]--) {
            arr[idx++] = i + mn;
        }
    }
}

void countingSortDigit(vector<int>& arr, long long exp) {
    int n = static_cast<int>(arr.size());
    vector<int> output(n);
    int cnt[10] = {};
    for (int x : arr) {
        int digit = static_cast<int>((x / exp) % 10);
        cnt[digit]++;
    }
    for (int i = 1; i < 10; i++) cnt[i] += cnt[i - 1];
    for (int i = n - 1; i >= 0; i--) {
        int digit = static_cast<int>((arr[i] / exp) % 10);
        output[cnt[digit] - 1] = arr[i];
        cnt[digit]--;
    }
    arr = output;
}

void radixSort(vector<int>& arr) {
    if (arr.empty()) return;
    int mx = 0;
    for (int x : arr) {
        if (x < 0) throw invalid_argument("radix sort expects non-negative integers");
        mx = max(mx, x);
    }
    for (long long exp = 1; mx / exp > 0; exp *= 10) {
        countingSortDigit(arr, exp);
    }
}

void bucketSort(vector<double>& arr) {
    int n = static_cast<int>(arr.size());
    if (n <= 1) return;

    auto [minIt, maxIt] = minmax_element(arr.begin(), arr.end());
    double mn = *minIt;
    double mx = *maxIt;
    if (mn == mx) return;

    vector<vector<double>> buckets(n);
    for (double x : arr) {
        int idx = static_cast<int>((x - mn) / (mx - mn) * (n - 1));
        idx = max(0, min(n - 1, idx));
        buckets[idx].push_back(x);
    }

    int pos = 0;
    for (auto& bucket : buckets) {
        sort(bucket.begin(), bucket.end());
        for (double x : bucket) {
            arr[pos++] = x;
        }
    }
}

void sort012(vector<int>& arr) {
    int low = 0;
    int mid = 0;
    int high = arr.size() - 1;
    while (mid <= high) {
        if (arr[mid] == 0) {
            swap(arr[low], arr[mid]);
            low++;
            mid++;
        } else if (arr[mid] == 1) {
            mid++;
        } else {
            swap(arr[mid], arr[high]);
            high--;
        }
    }
}

void sortByCustomComparator(vector<pair<int, int>>& arr) {
    sort(arr.begin(), arr.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second > b.second;
    });
}

vector<vector<int>> mergeIntervals(vector<vector<int>>& intervals) {
    if (intervals.empty()) return {};
    sort(intervals.begin(), intervals.end());
    vector<vector<int>> ans;
    ans.push_back(intervals[0]);
    for (int i = 1; i < intervals.size(); i++) {
        if (intervals[i][0] <= ans.back()[1]) {
            ans.back()[1] = max(ans.back()[1], intervals[i][1]);
        } else {
            ans.push_back(intervals[i]);
        }
    }
    return ans;
}

long long mergeAndCount(vector<int>& arr, int l, int mid, int r) {
    vector<int> temp;
    int i = l;
    int j = mid + 1;
    long long inv = 0;
    while (i <= mid && j <= r) {
        if (arr[i] <= arr[j]) {
            temp.push_back(arr[i++]);
        } else {
            temp.push_back(arr[j++]);
            inv += mid - i + 1;
        }
    }
    while (i <= mid) temp.push_back(arr[i++]);
    while (j <= r) temp.push_back(arr[j++]);
    for (int k = 0; k < temp.size(); k++) {
        arr[l + k] = temp[k];
    }
    return inv;
}
long long countInversions(vector<int>& arr, int l, int r) {
    if (l >= r) return 0;
    int mid = l + (r - l) / 2;
    long long ans = 0;
    ans += countInversions(arr, l, mid);
    ans += countInversions(arr, mid + 1, r);
    ans += mergeAndCount(arr, l, mid, r);
    return ans;
}

vector<int> coordinateCompress(vector<int> arr) {
    vector<int> vals = arr;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    vector<int> ans;
    for (int x : arr) {
        int rank = lower_bound(vals.begin(), vals.end(), x) - vals.begin();
        ans.push_back(rank);
    }
    return ans;
}

void quickSort3(vector<int>& arr, int l, int r) {
    if (l >= r) return;
    int pivot = arr[l];
    int lt = l;
    int i = l;
    int gt = r;
    while (i <= gt) {
        if (arr[i] < pivot) {
            swap(arr[lt], arr[i]);
            lt++;
            i++;
        } else if (arr[i] > pivot) {
            swap(arr[i], arr[gt]);
            gt--;
        } else {
            i++;
        }
    }
    quickSort3(arr, l, lt - 1);
    quickSort3(arr, gt + 1, r);
}

int countBits(unsigned int x) {
    int count = 0;
    while (x) {
