}

bool isSet(unsigned int x, int i) {
    if (i < 0 || i >= 32) return false;
    return ((x >> i) & 1U) != 0;
}

unsigned int setBit(unsigned int x, int i) {
    if (i < 0 || i >= 32) return x;
    return x | (1U << i);
}

unsigned int clearBit(unsigned int x, int i) {
    if (i < 0 || i >= 32) return x;
    return x & ~(1U << i);
