int singleNumber(vector<int>& arr) {
    int ans = 0;
    for (int x : arr) ans ^= x;
    return ans;
}

pair<int, int> twoUniques(const vector<int>& arr) {
    int xorAll = 0;
    for (int x : arr) xorAll ^= x;

    unsigned int bit = static_cast<unsigned int>(xorAll) & (0U - static_cast<unsigned int>(xorAll));
    int a = 0;
    int b = 0;
    for (int x : arr) {
        if ((static_cast<unsigned int>(x) & bit) != 0U) {
            a ^= x;
        } else {
            b ^= x;
        }
    }
    return {a, b};
}

int singleNumber3(vector<int>& arr) {
    int ones = 0;
    int twos = 0;
    for (int x : arr) {
        ones = (ones ^ x) & ~twos;
        twos = (twos ^ x) & ~ones;
    }
    return ones;
}

int missingNumber(vector<int>& arr) {
    int n = arr.size();
    int ans = n;
    for (int i = 0; i < n; i++) ans ^= i ^ arr[i];
    return ans;
}

