long long extendedGCD(long long a, long long b, long long& x, long long& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long x1, y1;
    long long g = extendedGCD(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

long long modExp(long long a, long long b, long long m) {
    if (m <= 0) throw invalid_argument("modulus must be positive");
    if (b < 0) throw invalid_argument("exponent must be non-negative");
    long long res = 1 % m;
    a %= m;
    if (a < 0) a += m;
    while (b > 0) {
        if ((b & 1LL) != 0) {
            res = static_cast<long long>((__int128)res * a % m);
        }
        a = static_cast<long long>((__int128)a * a % m);
        b >>= 1LL;
    }
    return res;
}

long long extendedGCD(long long a, long long b, long long& x, long long& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long x1, y1;
    long long g = extendedGCD(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

long long modInverse(long long a, long long m) {
    if (m <= 1) return -1;
    a %= m;
    if (a < 0) a += m;
    long long x, y;
    long long g = extendedGCD(a, m, x, y);
    if (g != 1) return -1;
    return (x % m + m) % m;
}

vector<bool> sieve(int n) {
    vector<bool> prime(n + 1, true);
    if (n >= 0) prime[0] = false;
    if (n >= 1) prime[1] = false;
    for (int i = 2; i * i <= n; i++) {
        if (prime[i]) {
            for (int j = i * i; j <= n; j += i) {
                prime[j] = false;
            }
        }
    }
    return prime;
}

vector<long long> primeFactors(long long n) {
    vector<long long> factors;
    for (long long i = 2; i * i <= n; i++) {
        while (n % i == 0) {
            factors.push_back(i);
            n /= i;
        }
    }
    if (n > 1) factors.push_back(n);
    return factors;
}

vector<int> sieveSPF(int n) {
    vector<int> spf(n + 1);
    for (int i = 0; i <= n; i++) spf[i] = i;
    if (n >= 0) spf[0] = 0;
    if (n >= 1) spf[1] = 1;
    for (int i = 2; i * i <= n; i++) {
        if (spf[i] == i) {
            for (int j = i * i; j <= n; j += i) {
                if (spf[j] == j) spf[j] = i;
            }
        }
    }
    return spf;
}

vector<int> getFactors(int x, const vector<int>& spf) {
