    while (x != 1) {
        factors.push_back(spf[x]);
        x /= spf[x];
    }
    return factors;
}

long long phi(long long n) {
    long long result = n;
    for (long long p = 2; p * p <= n; p++) {
        if (n % p == 0) {
            while (n % p == 0) n /= p;
            result -= result / p;
        }
    }
    if (n > 1) result -= result / n;
    return result;
}

long long modMul(long long a, long long b, long long m) {
    if (m <= 0) throw invalid_argument("modulus must be positive");
    a %= m;
    b %= m;
    if (a < 0) a += m;
    if (b < 0) b += m;

    long long res = 0;
    while (b > 0) {
        if ((b & 1LL) != 0) {
            if (res >= m - a) {
                res -= m - a;
            } else {
                res += a;
            }
        }
        b >>= 1LL;
        if (b == 0) break;
        if (a >= m - a) {
            a -= m - a;
        } else {
            a += a;
        }
    }
    return res;
}

long long modMul(long long a, long long b, long long m) {
    return (__int128)a * b % m;
}

bool isPrime(long long n, int k = 5) {
    static_cast<void>(k);
    if (n < 2) return false;
    for (long long p : {2LL, 3LL, 5LL, 7LL, 11LL, 13LL, 17LL, 19LL, 23LL, 29LL, 31LL, 37LL}) {
        if (n % p == 0) return n == p;
    }

    auto modMul = [&](long long a, long long b, long long mod) -> long long {
        return static_cast<long long>((__int128)a * b % mod);
    };
    auto modPow = [&](long long a, long long d, long long mod) -> long long {
        long long res = 1 % mod;
        a %= mod;
        while (d > 0) {
            if ((d & 1LL) != 0) res = modMul(res, a, mod);
            a = modMul(a, a, mod);
            d >>= 1LL;
        }
        return res;
    };

    long long d = n - 1;
    int s = 0;
    while ((d & 1LL) == 0) {
        d >>= 1LL;
        s++;
    }

    auto composite = [&](long long a) -> bool {
        if (a % n == 0) return false;
        long long x = modPow(a, d, n);
        if (x == 1 || x == n - 1) return false;
        for (int r = 1; r < s; r++) {
            x = modMul(x, x, n);
            if (x == n - 1) return false;
        }
        return true;
    };

    for (long long a : {2LL, 325LL, 9375LL, 28178LL, 450775LL, 9780504LL, 1795265022LL}) {
        if (composite(a)) return false;
    }
    return true;
}

long long extendedGCD(long long a, long long b, long long& x, long long& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long x1, y1;
    long long g = extendedGCD(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

long long modInverse(long long a, long long m) {
    a %= m;
    if (a < 0) a += m;
    long long x, y;
    long long g = extendedGCD(a, m, x, y);
    if (g != 1) return -1;
    return (x % m + m) % m;
}

long long CRT(const vector<long long>& nums, const vector<long long>& rems) {
    if (nums.empty() || nums.size() != rems.size()) {
        throw invalid_argument("nums and rems must be non-empty and have the same size");
    }

    __int128 prod = 1;
    for (long long mod : nums) {
        if (mod <= 0) throw invalid_argument("moduli must be positive");
        prod *= mod;
        if (prod > LLONG_MAX) {
            throw overflow_error("combined modulus exceeds 64-bit range");
        }
    }

    long long modAll = static_cast<long long>(prod);
    __int128 result = 0;
    for (int i = 0; i < static_cast<int>(nums.size()); i++) {
        long long mod = nums[i];
        long long residue = rems[i] % mod;
        if (residue < 0) residue += mod;

        long long pp = modAll / mod;
        long long inv = modInverse(pp % mod, mod);
        if (inv == -1) return -1;

        result += (__int128)residue * inv % modAll * pp;
        result %= modAll;
    }

    result %= modAll;
    if (result < 0) result += modAll;
    return static_cast<long long>(result);
}

long long binaryGCD(long long a, long long b) {
    if (a == 0) return b;
    if (b == 0) return a;
    int shift = 0;
    // Both even
    while (((a | b) & 1) == 0) {
        a >>= 1;
        b >>= 1;
        shift++;
    }
    // Make a odd
    while ((a & 1) == 0) a >>= 1;
    while (b != 0) {
        // Make b odd
        while ((b & 1) == 0) b >>= 1;
        if (a > b) swap(a, b);
        b -= a;
    }
    return a << shift;
}

vector<long long> fact;
vector<long long> invFact;

long long modPow(long long a, long long b, long long p) {
    long long res = 1 % p;
    a %= p;
    if (a < 0) a += p;
    while (b > 0) {
        if ((b & 1LL) != 0) {
            res = static_cast<long long>((__int128)res * a % p);
        }
        a = static_cast<long long>((__int128)a * a % p);
        b >>= 1LL;
    }
    return res;
}

void precompute(int N, long long p) {
    if (N < 0) throw invalid_argument("N must be non-negative");
    if (p <= 1) throw invalid_argument("p must be prime");
    if (N >= p) throw invalid_argument("this method requires N < p");

    fact.assign(N + 1, 1);
    invFact.assign(N + 1, 1);
    for (int i = 1; i <= N; i++) {
        fact[i] = static_cast<long long>((__int128)fact[i - 1] * i % p);
    }
    invFact[N] = modPow(fact[N], p - 2, p);
    for (int i = N - 1; i >= 0; i--) {
        invFact[i] = static_cast<long long>((__int128)invFact[i + 1] * (i + 1) % p);
    }
}

long long nCr(int n, int r, long long p) {
    if (r < 0 || r > n) return 0;
    if (n >= static_cast<int>(fact.size())) {
        throw out_of_range("call precompute with N >= n first");
    }
    return static_cast<long long>((__int128)fact[n] * invFact[r] % p * invFact[n - r] % p);
}

string longestPalindrome(string s) {
    int n = s.size();
    int bestL = 0, bestR = 0;
    auto expand = [&](int l, int r) {
        while (l >= 0 && r < n && s[l] == s[r]) {
            if (r - l > bestR - bestL) {
                bestL = l;
                bestR = r;
            }
            l--;
            r++;
        }
    };
    for (int i = 0; i < n; i++) {
        expand(i, i);      // Odd length
        expand(i, i + 1);  // Even length
    }
    return s.substr(bestL, bestR - bestL + 1);
}

int LCS(string a, string b) {
    int n = a.size();
    int m = b.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] = 1 + dp[i - 1][j - 1];
            } else {
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    return dp[n][m];
}

int longestCommonSubstring(string a, string b) {
    int n = a.size();
    int m = b.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    int ans = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                ans = max(ans, dp[i][j]);
            }
        }
    }
    return ans;
}

int editDistance(string a, string b) {
    int n = a.size();
    int m = b.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1));
    for (int i = 0; i <= n; i++) dp[i][0] = i;
    for (int j = 0; j <= m; j++) dp[0][j] = j;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = 1 + min({
                                   dp[i - 1][j],     // Delete
                                   dp[i][j - 1],     // Insert
                                   dp[i - 1][j - 1]  // Replace
                               });
            }
        }
    }
    return dp[n][m];
}

vector<int> computeLPS(string pat) {
    int n = pat.size();
    vector<int> lps(n, 0);
    int len = 0;
    for (int i = 1; i < n; i++) {
        while (len > 0 && pat[i] != pat[len]) {
            len = lps[len - 1];
        }
        if (pat[i] == pat[len]) len++;
        lps[i] = len;
    }
    return lps;
}

vector<int> computeLPS(const string& pat) {
    int n = static_cast<int>(pat.size());
    vector<int> lps(n, 0);
    int len = 0;
    for (int i = 1; i < n; i++) {
        while (len > 0 && pat[i] != pat[len]) {
            len = lps[len - 1];
        }
        if (pat[i] == pat[len]) len++;
        lps[i] = len;
    }
    return lps;
}

vector<int> KMP(const string& text, const string& pat) {
    vector<int> ans;
    if (pat.empty()) return ans;

    vector<int> lps = computeLPS(pat);
    int n = static_cast<int>(text.size());
    int m = static_cast<int>(pat.size());
    int i = 0;
    int j = 0;
    while (i < n) {
        if (text[i] == pat[j]) {
            i++;
            j++;
            if (j == m) {
                ans.push_back(i - j);
                j = lps[j - 1];
            }
        } else if (j > 0) {
            j = lps[j - 1];
        } else {
            i++;
        }
    }
    return ans;
}

vector<int> ZAlgorithm(string s) {
    int n = s.size();
    vector<int> z(n, 0);
    int l = 0;
    int r = 0;
    for (int i = 1; i < n; i++) {
        if (i <= r) z[i] = min(r - i + 1, z[i - l]);
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) {
            z[i]++;
        }
        if (i + z[i] - 1 > r) {
            l = i;
            r = i + z[i] - 1;
        }
    }
    return z;
}

vector<int> rabinKarp(const string& text, const string& pat) {
    vector<int> ans;
    int n = static_cast<int>(text.size());
    int m = static_cast<int>(pat.size());
    if (m == 0 || m > n) return ans;

    const long long MOD = 1000000007;
    const long long BASE = 911382323;
    auto value = [](unsigned char c) -> long long { return static_cast<long long>(c) + 1; };

    long long patHash = 0;
    long long textHash = 0;
    long long power = 1;
    for (int i = 0; i < m; i++) {
        patHash = (patHash * BASE + value(static_cast<unsigned char>(pat[i]))) % MOD;
        textHash = (textHash * BASE + value(static_cast<unsigned char>(text[i]))) % MOD;
        if (i + 1 < m) power = power * BASE % MOD;
    }

    for (int i = 0; i <= n - m; i++) {
        if (patHash == textHash && text.compare(i, m, pat) == 0) {
            ans.push_back(i);
        }
        if (i < n - m) {
            textHash = (textHash - value(static_cast<unsigned char>(text[i])) * power % MOD + MOD) % MOD;
            textHash = (textHash * BASE + value(static_cast<unsigned char>(text[i + m]))) % MOD;
        }
    }
    return ans;
}

string manacher(string s) {
    string t = "^";
    for (char c : s) {
        t += '#';
        t += c;
    }
    t += "#$";
    int n = t.size();
    vector<int> p(n, 0);
    int center = 0;
    int right = 0;
    int bestCenter = 0;
    int bestLen = 0;
    for (int i = 1; i < n - 1; i++) {
        int mirror = 2 * center - i;
        if (i < right) p[i] = min(right - i, p[mirror]);
        while (t[i + 1 + p[i]] == t[i - 1 - p[i]]) {
            p[i]++;
        }
        if (i + p[i] > right) {
            center = i;
            right = i + p[i];
        }
        if (p[i] > bestLen) {
            bestLen = p[i];
            bestCenter = i;
        }
    }
    int start = (bestCenter - bestLen) / 2;
    return s.substr(start, bestLen);
}

class Trie {
    struct Node {
        Node* child[26];
        bool end;
        Node() {
            end = false;
            for (int i = 0; i < 26; i++) child[i] = nullptr;
        }
    };
    Node* root;

   public:
    Trie() {
        root = new Node();
    }
    void insert(string word) {
        Node* cur = root;
        for (char c : word) {
            int x = c - 'a';
            if (!cur->child[x]) cur->child[x] = new Node();
            cur = cur->child[x];
        }
        cur->end = true;
    }
    bool search(string word) {
        Node* cur = root;
        for (char c : word) {
            int x = c - 'a';
            if (!cur->child[x]) return false;
            cur = cur->child[x];
        }
        return cur->end;
    }
    bool startsWith(string prefix) {
        Node* cur = root;
        for (char c : prefix) {
            int x = c - 'a';
            if (!cur->child[x]) return false;
            cur = cur->child[x];
        }
        return true;
    }
};

class AhoCorasick {
    static constexpr int ALPHABET = 256;

    struct Node {
        array<int, ALPHABET> child;
        int link;
        vector<int> output;
        Node() : link(0) {
            child.fill(-1);
        }
    };

    vector<Node> trie;
    vector<int> patternLength;

   public:
    AhoCorasick() : trie(1) {}

    void insert(const string& s, int id) {
        if (id >= static_cast<int>(patternLength.size())) {
            patternLength.resize(id + 1, 0);
        }
        patternLength[id] = static_cast<int>(s.size());

        int cur = 0;
        for (char c : s) {
            int x = static_cast<unsigned char>(c);
            if (trie[cur].child[x] == -1) {
                trie[cur].child[x] = static_cast<int>(trie.size());
                trie.emplace_back();
            }
            cur = trie[cur].child[x];
        }
        trie[cur].output.push_back(id);
    }

    void build() {
        queue<int> q;
        for (int c = 0; c < ALPHABET; c++) {
            int nxt = trie[0].child[c];
            if (nxt != -1) {
                trie[nxt].link = 0;
                q.push(nxt);
            } else {
                trie[0].child[c] = 0;
            }
        }

        while (!q.empty()) {
            int v = q.front();
            q.pop();

            const auto& failOutput = trie[trie[v].link].output;
            trie[v].output.insert(trie[v].output.end(), failOutput.begin(), failOutput.end());

            for (int c = 0; c < ALPHABET; c++) {
                int nxt = trie[v].child[c];
                if (nxt != -1) {
                    trie[nxt].link = trie[trie[v].link].child[c];
                    q.push(nxt);
                } else {
                    trie[v].child[c] = trie[trie[v].link].child[c];
                }
            }
        }
    }

    vector<pair<int, int>> search(const string& text) const {
        vector<pair<int, int>> matches;
        int state = 0;
        for (int i = 0; i < static_cast<int>(text.size()); i++) {
            state = trie[state].child[static_cast<unsigned char>(text[i])];
            for (int id : trie[state].output) {
                matches.push_back({i - patternLength[id] + 1, id});
            }
        }
        return matches;
    }
};

class StringHash {
    static const long long MOD = 1000000007;
    static const long long BASE = 911382323;
    vector<long long> h;
    vector<long long> power;

   public:
    explicit StringHash(const string& s) {
        int n = static_cast<int>(s.size());
        h.assign(n + 1, 0);
        power.assign(n + 1, 1);
        for (int i = 0; i < n; i++) {
            long long value = static_cast<unsigned char>(s[i]) + 1;
            h[i + 1] = (h[i] * BASE + value) % MOD;
            power[i + 1] = power[i] * BASE % MOD;
        }
    }

    long long getHash(int l, int r) const {
        int n = static_cast<int>(h.size()) - 1;
        if (l < 0 || r < l || r > n) {
            throw out_of_range("invalid substring range");
        }
        return (h[r] - h[l] * power[r - l] % MOD + MOD) % MOD;
    }
};

bool equalSubstrings(const StringHash& H, int l1, int r1, int l2, int r2) {
    if (r1 - l1 != r2 - l2) return false;
    return H.getHash(l1, r1) == H.getHash(l2, r2);
}

int longestPalindromicSubsequence(const string& s) {
    int n = static_cast<int>(s.size());
    if (n == 0) return 0;

    vector<vector<int>> dp(n, vector<int>(n, 0));
    for (int i = 0; i < n; i++) dp[i][i] = 1;

    for (int len = 2; len <= n; len++) {
        for (int l = 0; l + len - 1 < n; l++) {
            int r = l + len - 1;
            if (s[l] == s[r]) {
                dp[l][r] = 2 + (len == 2 ? 0 : dp[l + 1][r - 1]);
            } else {
                dp[l][r] = max(dp[l + 1][r], dp[l][r - 1]);
            }
        }
    }
    return dp[0][n - 1];
}

string minWindow(const string& s, const string& t) {
    if (t.empty() || s.empty() || t.size() > s.size()) return "";

    array<int, 256> need{};
    array<int, 256> window{};
    for (char c : t) need[static_cast<unsigned char>(c)]++;

    int missing = static_cast<int>(t.size());
    int bestLen = INT_MAX;
    int bestL = 0;
    int l = 0;

    for (int r = 0; r < static_cast<int>(s.size()); r++) {
        unsigned char rc = static_cast<unsigned char>(s[r]);
        if (need[rc] > 0 && window[rc] < need[rc]) missing--;
        window[rc]++;

        while (missing == 0) {
            if (r - l + 1 < bestLen) {
                bestLen = r - l + 1;
                bestL = l;
            }

            unsigned char lc = static_cast<unsigned char>(s[l]);
            window[lc]--;
            if (need[lc] > 0 && window[lc] < need[lc]) missing++;
            l++;
        }
    }

    return bestLen == INT_MAX ? "" : s.substr(bestL, bestLen);
}

string smallestSubsequence(string s) {
    vector<int> last(256, -1);
    for (int i = 0; i < s.size(); i++) last[(unsigned char)s[i]] = i;
    vector<bool> seen(256, false);
    string st;
    for (int i = 0; i < s.size(); i++) {
        unsigned char c = s[i];
        if (seen[c]) continue;
        while (!st.empty() && st.back() > c && last[(unsigned char)st.back()] > i) {
            seen[(unsigned char)st.back()] = false;
            st.pop_back();
        }
        st.push_back(c);
        seen[c] = true;
    }
    return st;
}

vector<int> suffixArray(string s) {
    int n = s.size();
    vector<int> sa(n);
    vector<int> rank(n);
    for (int i = 0; i < n; i++) {
        sa[i] = i;
        rank[i] = s[i];
    }
    for (int k = 1; k < n; k *= 2) {
        auto cmp = [&](int i, int j) {
            if (rank[i] != rank[j]) return rank[i] < rank[j];
            int ri = i + k < n ? rank[i + k] : -1;
            int rj = j + k < n ? rank[j + k] : -1;
            return ri < rj;
        };
        sort(sa.begin(), sa.end(), cmp);
        vector<int> newRank(n);
        newRank[sa[0]] = 0;
        for (int i = 1; i < n; i++) {
            newRank[sa[i]] = newRank[sa[i - 1]] + cmp(sa[i - 1], sa[i]);
        }
        rank = newRank;
        if (rank[sa[n - 1]] == n - 1) break;
    }
    return sa;
}

vector<int> buildLCP(string s, vector<int>& sa) {
    int n = s.size();
    vector<int> rank(n);
    for (int i = 0; i < n; i++) rank[sa[i]] = i;
    vector<int> lcp(n, 0);
    int k = 0;
    for (int i = 0; i < n; i++) {
        if (rank[i] == n - 1) {
            k = 0;
            continue;
        }
        int j = sa[rank[i] + 1];
        while (i + k < n && j + k < n && s[i + k] == s[j + k]) {
            k++;
        }
        lcp[rank[i]] = k;
        if (k > 0) k--;
    }
    return lcp;
}

long long countDistinctSubstrings(int n, vector<int>& lcp) {
    long long total = 1LL * n * (n + 1) / 2;
    for (int x : lcp) total -= x;
    return total;
}

bool wordBreak(string s, vector<string>& words) {
    unordered_set<string> dict(words.begin(), words.end());
    int n = s.size();
    vector<bool> dp(n + 1, false);
    dp[0] = true;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < i; j++) {
            if (dp[j] && dict.count(s.substr(j, i - j))) {
                dp[i] = true;
                break;
            }
        }
    }
    return dp[n];
}

class SuffixAutomaton {
    static constexpr int ALPHABET = 256;

    struct State {
        int len = 0;
        int link = -1;
        array<int, ALPHABET> next;
        State() {
            next.fill(-1);
        }
    };

    vector<State> st;
    int last = 0;

   public:
    SuffixAutomaton() : st(1) {}

    void extend(char ch) {
        int c = static_cast<unsigned char>(ch);
        int cur = static_cast<int>(st.size());
        st.emplace_back();
        st[cur].len = st[last].len + 1;

        int p = last;
        while (p != -1 && st[p].next[c] == -1) {
            st[p].next[c] = cur;
            p = st[p].link;
        }

        if (p == -1) {
            st[cur].link = 0;
        } else {
            int q = st[p].next[c];
            if (st[p].len + 1 == st[q].len) {
                st[cur].link = q;
            } else {
                int clone = static_cast<int>(st.size());
                st.push_back(st[q]);
                st[clone].len = st[p].len + 1;
                while (p != -1 && st[p].next[c] == q) {
                    st[p].next[c] = clone;
                    p = st[p].link;
                }
                st[q].link = clone;
                st[cur].link = clone;
            }
        }
        last = cur;
    }

    void build(const string& s) {
        st.assign(1, State());
        last = 0;
        for (char c : s) extend(c);
    }

    bool contains(const string& pattern) const {
        int state = 0;
        for (char c : pattern) {
            state = st[state].next[static_cast<unsigned char>(c)];
            if (state == -1) return false;
        }
        return true;
    }
};

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};
ListNode* reverseList(ListNode* head) {
    ListNode* prev = nullptr;
    ListNode* curr = head;
    while (curr) {
        ListNode* next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

ListNode* reverseRecursive(ListNode* head) {
    if (!head || !head->next) return head;
    ListNode* newHead = reverseRecursive(head->next);
    head->next->next = head;
    head->next = nullptr;
    return newHead;
}

ListNode* reverseKGroup(ListNode* head, int k) {
    ListNode* curr = head;
    int count = 0;
    while (curr && count < k) {
        curr = curr->next;
        count++;
    }
    if (count < k) return head;
    curr = head;
    ListNode* prev = nullptr;
    for (int i = 0; i < k; i++) {
        ListNode* next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    }
    head->next = reverseKGroup(curr, k);
    return prev;
}

ListNode* reverseBetween(ListNode* head, int left, int right) {
    if (!head || left == right) return head;
    ListNode dummy(0);
    dummy.next = head;
    ListNode* prev = &dummy;
    for (int i = 1; i < left; i++) prev = prev->next;
    ListNode* curr = prev->next;
    for (int i = 0; i < right - left; i++) {
        ListNode* next = curr->next;
        curr->next = next->next;
        next->next = prev->next;
        prev->next = next;
    }
    return dummy.next;
}

bool hasCycle(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

ListNode* detectCycle(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            slow = head;
            while (slow != fast) {
                slow = slow->next;
                fast = fast->next;
            }
            return slow;
        }
    }
    return nullptr;
}

ListNode* middleNode(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;
}

ListNode* reverseList(ListNode* head) {
    ListNode* prev = nullptr;
    while (head) {
        ListNode* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}
bool isPalindrome(ListNode* head) {
    if (!head || !head->next) return true;
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast->next && fast->next->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    ListNode* secondHalf = reverseList(slow->next);
    ListNode* copy = secondHalf;
    ListNode* firstHalf = head;
    bool ok = true;
    while (copy) {
        if (firstHalf->val != copy->val) {
            ok = false;
            break;
        }
        firstHalf = firstHalf->next;
        copy = copy->next;
    }
    slow->next = reverseList(secondHalf);
    return ok;
}

ListNode* mergeTwoLists(ListNode* l1, ListNode* l2) {
    ListNode dummy(0);
    ListNode* tail = &dummy;
    while (l1 && l2) {
        if (l1->val <= l2->val) {
            tail->next = l1;
            l1 = l1->next;
        } else {
            tail->next = l2;
            l2 = l2->next;
        }
        tail = tail->next;
    }
    tail->next = l1 ? l1 : l2;
    return dummy.next;
}

struct Compare {
    bool operator()(ListNode* a, ListNode* b) {
        return a->val > b->val;
    }
};
ListNode* mergeKLists(vector<ListNode*>& lists) {
    priority_queue<ListNode*, vector<ListNode*>, Compare> pq;
    for (ListNode* head : lists) {
        if (head) pq.push(head);
    }
    ListNode dummy(0);
    ListNode* tail = &dummy;
    while (!pq.empty()) {
        ListNode* node = pq.top();
        pq.pop();
        tail->next = node;
        tail = node;
        if (node->next) pq.push(node->next);
    }
    return dummy.next;
}

ListNode* mergeTwoLists(ListNode* l1, ListNode* l2) {
    ListNode dummy(0);
    ListNode* tail = &dummy;
    while (l1 && l2) {
        if (l1->val <= l2->val) {
            tail->next = l1;
            l1 = l1->next;
        } else {
            tail->next = l2;
            l2 = l2->next;
        }
        tail = tail->next;
    }
    tail->next = l1 ? l1 : l2;
    return dummy.next;
}
ListNode* mergeRange(vector<ListNode*>& lists, int l, int r) {
    if (l == r) return lists[l];
    int mid = l + (r - l) / 2;
    ListNode* left = mergeRange(lists, l, mid);
    ListNode* right = mergeRange(lists, mid + 1, r);
    return mergeTwoLists(left, right);
}
ListNode* mergeKListsDC(vector<ListNode*>& lists) {
    if (lists.empty()) return nullptr;
    return mergeRange(lists, 0, static_cast<int>(lists.size()) - 1);
}

ListNode* removeNthFromEnd(ListNode* head, int n) {
    if (!head || n <= 0) return head;
    ListNode dummy(0);
    dummy.next = head;
    ListNode* first = &dummy;
    for (int i = 0; i < n && first; i++) {
        first = first->next;
    }
    if (!first) return head;
    ListNode* second = &dummy;
    while (first->next) {
        first = first->next;
        second = second->next;
    }
    ListNode* node = second->next;
    if (!node) return head;
    second->next = node->next;
    return dummy.next;
}

void deleteNode(ListNode* node) {
    node->val = node->next->val;
    node->next = node->next->next;
}

ListNode* mergeTwoLists(ListNode* l1, ListNode* l2) {
    ListNode dummy(0);
    ListNode* tail = &dummy;
    while (l1 && l2) {
        if (l1->val <= l2->val) {
            tail->next = l1;
            l1 = l1->next;
        } else {
            tail->next = l2;
            l2 = l2->next;
        }
        tail = tail->next;
    }
