ListNode* sortList(ListNode* head) {
    if (!head || !head->next) return head;
    ListNode* slow = head;
    ListNode* fast = head->next;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    ListNode* mid = slow->next;
    slow->next = nullptr;
    ListNode* left = sortList(head);
    ListNode* right = sortList(mid);
    return mergeTwoLists(left, right);
}

ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
    ListNode dummy(0);
    ListNode* curr = &dummy;
    int carry = 0;
    while (l1 || l2 || carry) {
        int sum = carry;
        if (l1) {
            sum += l1->val;
            l1 = l1->next;
        }
        if (l2) {
            sum += l2->val;
            l2 = l2->next;
        }
        curr->next = new ListNode(sum % 10);
        carry = sum / 10;
        curr = curr->next;
    }
    return dummy.next;
}

struct Node {
    int val;
    Node* prev;
    Node* next;
    Node* child;
};
Node* flatten(Node* head) {
    if (!head) return head;
    Node* curr = head;
    while (curr) {
        if (curr->child) {
            Node* child = curr->child;
            Node* next = curr->next;
            curr->next = child;
            child->prev = curr;
            curr->child = nullptr;
            Node* tail = child;
            while (tail->next) tail = tail->next;
            tail->next = next;
            if (next) next->prev = tail;
        }
        curr = curr->next;
    }
    return head;
}

Node* flattenTail(Node* head) {
    Node* curr = head;
    Node* tail = head;
    while (curr) {
        Node* next = curr->next;
        if (curr->child) {
            Node* childHead = curr->child;
            Node* childTail = flattenTail(childHead);
            curr->child = nullptr;
            curr->next = childHead;
            childHead->prev = curr;
            if (next) {
                childTail->next = next;
                next->prev = childTail;
            }
            tail = childTail;
            curr = childTail;
        } else {
            tail = curr;
        }
        curr = curr->next;
    }
    return tail;
}
Node* flattenDFS(Node* head) {
    if (!head) return nullptr;
    flattenTail(head);
    return head;
}

struct RandomNode {
    int val;
    RandomNode* next;
    RandomNode* random;
    RandomNode(int x) : val(x), next(nullptr), random(nullptr) {}
};
RandomNode* copyRandomList(RandomNode* head) {
    if (!head) return nullptr;
    unordered_map<RandomNode*, RandomNode*> mp;
    RandomNode* curr = head;
    while (curr) {
        mp[curr] = new RandomNode(curr->val);
        curr = curr->next;
    }
    curr = head;
    while (curr) {
        mp[curr]->next = curr->next ? mp[curr->next] : nullptr;
        mp[curr]->random = curr->random ? mp[curr->random] : nullptr;
        curr = curr->next;
    }
    return mp[head];
}

RandomNode* copyRandomListO1(RandomNode* head) {
    if (!head) return nullptr;
    // 1. Insert copied node after every node
    RandomNode* curr = head;
    while (curr) {
        RandomNode* copy = new RandomNode(curr->val);
        copy->next = curr->next;
        curr->next = copy;
        curr = copy->next;
    }
    // 2. Set random pointers
    curr = head;
    while (curr) {
        if (curr->random) curr->next->random = curr->random->next;
        curr = curr->next->next;
    }
    // 3. Separate the lists
    curr = head;
    RandomNode* newHead = head->next;
    while (curr) {
        RandomNode* copy = curr->next;
        curr->next = copy->next;
        if (copy->next) copy->next = copy->next->next;
        curr = curr->next;
    }
    return newHead;
}

ListNode* getIntersectionNode(ListNode* headA, ListNode* headB) {
    ListNode* a = headA;
    ListNode* b = headB;
    while (a != b) {
        a = a ? a->next : headB;
        b = b ? b->next : headA;
    }
    return a;
}

ListNode* reverseList(ListNode* head) {
    ListNode* prev = nullptr;
    while (head) {
        ListNode* next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}
void reorderList(ListNode* head) {
    if (!head || !head->next) return;
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast->next && fast->next->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    ListNode* second = reverseList(slow->next);
    slow->next = nullptr;
    ListNode* first = head;
    while (second) {
        ListNode* next1 = first->next;
        ListNode* next2 = second->next;
        first->next = second;
        second->next = next1;
        first = next1;
        second = next2;
    }
}

ListNode* partition(ListNode* head, int x) {
    ListNode smallDummy(0);
    ListNode largeDummy(0);
    ListNode* small = &smallDummy;
    ListNode* large = &largeDummy;
    while (head) {
        if (head->val < x) {
            small->next = head;
            small = small->next;
        } else {
            large->next = head;
            large = large->next;
        }
        head = head->next;
    }
    large->next = nullptr;
    small->next = largeDummy.next;
    return smallDummy.next;
}

ListNode* oddEvenList(ListNode* head) {
    if (!head || !head->next) return head;
    ListNode* odd = head;
    ListNode* even = head->next;
    ListNode* evenHead = even;
    while (even && even->next) {
        odd->next = even->next;
        odd = odd->next;
        even->next = odd->next;
        even = even->next;
    }
    odd->next = evenHead;
    return head;
}

int cycleLength(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            int len = 1;
            fast = fast->next;
            while (fast != slow) {
                fast = fast->next;
                len++;
            }
            return len;
        }
    }
    return 0;
}

void removeCycle(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) break;
    }
    if (!fast || !fast->next) return;
    slow = head;
    while (slow != fast) {
        slow = slow->next;
        fast = fast->next;
    }
    ListNode* cycleStart = slow;
    ListNode* curr = cycleStart;
    while (curr->next != cycleStart) curr = curr->next;
    curr->next = nullptr;
}

class LRUCache {
    struct Node {
        int key;
        int value;
        Node* prev;
        Node* next;
        Node(int k, int v) : key(k), value(v), prev(nullptr), next(nullptr) {}
    };
    int capacity;
    unordered_map<int, Node*> mp;
    Node* head;
    Node* tail;
    void remove(Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }
    void insertFront(Node* node) {
        node->next = head->next;
        node->prev = head;
        head->next->prev = node;
        head->next = node;
    }

   public:
    LRUCache(int capacity) {
        this->capacity = capacity;
        head = new Node(0, 0);
        tail = new Node(0, 0);
        head->next = tail;
        tail->prev = head;
    }
    int get(int key) {
        if (!mp.count(key)) return -1;
        Node* node = mp[key];
        remove(node);
        insertFront(node);
        return node->value;
    }
    void put(int key, int value) {
        if (mp.count(key)) {
            Node* node = mp[key];
            node->value = value;
            remove(node);
            insertFront(node);
            return;
        }
        Node* node = new Node(key, value);
        mp[key] = node;
        insertFront(node);
        if (mp.size() > capacity) {
            Node* lru = tail->prev;
            mp.erase(lru->key);
            remove(lru);
            delete lru;
        }
    }
};

vector<ListNode*> splitListToParts(ListNode* head, int k) {
    int n = 0;
    ListNode* curr = head;
    while (curr) {
        n++;
        curr = curr->next;
    }
    int base = n / k;
    int extra = n % k;
    vector<ListNode*> ans(k);
    curr = head;
    for (int i = 0; i < k; i++) {
        ans[i] = curr;
        int size = base + (i < extra);
        for (int j = 1; j < size; j++) {
            if (curr) curr = curr->next;
        }
        if (curr) {
            ListNode* next = curr->next;
            curr->next = nullptr;
            curr = next;
        }
    }
    return ans;
}

ListNode* rotateRight(ListNode* head, int k) {
    if (!head || !head->next || k == 0) return head;
    int n = 1;
    ListNode* tail = head;
    while (tail->next) {
        tail = tail->next;
        n++;
    }
    k %= n;
    if (k == 0) return head;
    tail->next = head;
    int steps = n - k;
    while (steps--) tail = tail->next;
    head = tail->next;
    tail->next = nullptr;
    return head;
}

ListNode* reverseAlternateK(ListNode* head, int k) {
    if (!head || k <= 1) return head;
    ListNode* curr = head;
    ListNode* prev = nullptr;
    int count = 0;
    while (curr && count < k) {
        ListNode* next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
        count++;
    }
    head->next = curr;
    ListNode* skip = curr;
    for (int i = 1; skip && i < k; i++) {
        skip = skip->next;
    }
    if (skip) skip->next = reverseAlternateK(skip->next, k);
    return prev;
}

