long long sumSubarrayMins(vector<int>& arr) {
    int n = arr.size();
    vector<int> left(n);
    vector<int> right(n);
    stack<int> st;
    // Previous smaller element
    for (int i = 0; i < n; i++) {
        while (!st.empty() && arr[st.top()] > arr[i]) {
            st.pop();
        }
        if (st.empty())
            left[i] = i + 1;
        else
            left[i] = i - st.top();
        st.push(i);
    }
    while (!st.empty()) st.pop();
    // Next smaller-or-equal element
    for (int i = n - 1; i >= 0; i--) {
        while (!st.empty() && arr[st.top()] >= arr[i]) {
            st.pop();
        }
        if (st.empty())
            right[i] = n - i;
        else
            right[i] = st.top() - i;
        st.push(i);
    }
    long long ans = 0;
    for (int i = 0; i < n; i++) {
        ans += 1LL * arr[i] * left[i] * right[i];
    }
    return ans;
}

long long sumSubarrayRanges(vector<int>& nums) {
    int n = nums.size();
    long long ans = 0;
    // Contribution as maximum
    stack<int> st;
    for (int i = 0; i <= n; i++) {
        while (!st.empty() && (i == n || nums[st.top()] < nums[i])) {
            int j = st.top();
            st.pop();
            int left = st.empty() ? j + 1 : j - st.top();
            int right = i - j;
            ans += 1LL * nums[j] * left * right;
        }
        st.push(i);
    }
    while (!st.empty()) st.pop();
    // Contribution as minimum
    for (int i = 0; i <= n; i++) {
        while (!st.empty() && (i == n || nums[st.top()] > nums[i])) {
            int j = st.top();
            st.pop();
            int left = st.empty() ? j + 1 : j - st.top();
            int right = i - j;
            ans -= 1LL * nums[j] * left * right;
        }
        st.push(i);
    }
    return ans;
}

vector<int> maxSlidingWindow(vector<int>& nums, int k) {
    deque<int> dq;
    vector<int> ans;
    for (int i = 0; i < nums.size(); i++) {
        // Remove expired indices
        while (!dq.empty() && dq.front() <= i - k) {
            dq.pop_front();
        }
        // Maintain decreasing values
        while (!dq.empty() && nums[dq.back()] <= nums[i]) {
            dq.pop_back();
        }
        dq.push_back(i);
        if (i >= k - 1) ans.push_back(nums[dq.front()]);
    }
    return ans;
}

vector<int> minSlidingWindow(vector<int>& nums, int k) {
    deque<int> dq;
    vector<int> ans;
    for (int i = 0; i < nums.size(); i++) {
        while (!dq.empty() && dq.front() <= i - k) {
            dq.pop_front();
        }
        while (!dq.empty() && nums[dq.back()] >= nums[i]) {
            dq.pop_back();
        }
        dq.push_back(i);
        if (i >= k - 1) ans.push_back(nums[dq.front()]);
    }
    return ans;
}

