int evalPostfix(vector<string>& tokens) {
    stack<int> st;
    for (string& token : tokens) {
        if (isdigit(token[0]) || (token.size() > 1 && token[0] == '-')) {
            st.push(stoi(token));
        } else {
            int b = st.top();
            st.pop();
            int a = st.top();
            st.pop();
            if (token == "+")
                st.push(a + b);
            else if (token == "-")
                st.push(a - b);
            else if (token == "*")
                st.push(a * b);
            else
                st.push(a / b);
        }
    }
    return st.top();
}

int precedence(char op) {
    if (op == '^') return 3;
    if (op == '*' || op == '/') return 2;
    if (op == '+' || op == '-') return 1;
    return 0;
}
bool isRightAssociative(char op) {
    return op == '^';
}
string infixToPostfix(string s) {
    stack<char> st;
    string ans;
    for (char c : s) {
        if (isspace(static_cast<unsigned char>(c))) continue;
        if (isalnum(static_cast<unsigned char>(c))) {
            ans += c;
        } else if (c == '(') {
            st.push(c);
        } else if (c == ')') {
            while (!st.empty() && st.top() != '(') {
                ans += st.top();
                st.pop();
            }
            if (!st.empty()) st.pop();
        } else {
            while (!st.empty() && st.top() != '(' &&
                   (precedence(st.top()) > precedence(c) ||
                    (precedence(st.top()) == precedence(c) && !isRightAssociative(c)))) {
                ans += st.top();
                st.pop();
            }
            st.push(c);
        }
    }
    while (!st.empty()) {
        if (st.top() != '(') ans += st.top();
        st.pop();
    }
    return ans;
}

int calculate(string s) {
    stack<int> st;
    int result = 0;
    int num = 0;
    int sign = 1;
    for (int i = 0; i < s.size(); i++) {
        char c = s[i];
        if (isdigit(c)) {
            num = 0;
            while (i < s.size() && isdigit(s[i])) {
                num = num * 10 + (s[i] - '0');
                i++;
            }
            i--;
            result += sign * num;
        } else if (c == '+') {
            sign = 1;
        } else if (c == '-') {
            sign = -1;
        } else if (c == '(') {
            st.push(result);
            st.push(sign);
            result = 0;
            sign = 1;
        } else if (c == ')') {
            int prevSign = st.top();
            st.pop();
            int prevResult = st.top();
            st.pop();
            result = prevResult + prevSign * result;
        }
    }
    return result;
}

string removeKdigits(string num, int k) {
    string st;
    for (char c : num) {
        while (!st.empty() && k > 0 && st.back() > c) {
            st.pop_back();
            k--;
        }
        st.push_back(c);
    }
    while (k > 0) {
        st.pop_back();
        k--;
    }
    int i = 0;
    while (i < st.size() && st[i] == '0') {
        i++;
    }
    string ans = st.substr(i);
    return ans.empty() ? "0" : ans;
}

string decodeString(string s) {
    stack<int> counts;
    stack<string> strings;
    string curr;
    int num = 0;
    for (char c : s) {
        if (isdigit(c)) {
            num = num * 10 + (c - '0');
        } else if (c == '[') {
            counts.push(num);
            strings.push(curr);
            num = 0;
            curr = "";
        } else if (c == ']') {
            int k = counts.top();
            counts.pop();
            string prev = strings.top();
            strings.pop();
            while (k--) prev += curr;
            curr = prev;
        } else {
            curr += c;
        }
    }
    return curr;
}

vector<int> asteroidCollision(vector<int>& asteroids) {
    vector<int> st;
    for (int x : asteroids) {
        bool alive = true;
        while (alive && x < 0 && !st.empty() && st.back() > 0) {
            if (st.back() < -x) {
                st.pop_back();
            } else if (st.back() == -x) {
                st.pop_back();
                alive = false;
            } else {
                alive = false;
            }
        }
        if (alive) st.push_back(x);
    }
    return st;
}

int trap(vector<int>& height) {
    int n = height.size();
    stack<int> st;
    int water = 0;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && height[i] > height[st.top()]) {
            int bottom = st.top();
            st.pop();
            if (st.empty()) break;
            int left = st.top();
            int width = i - left - 1;
            int h = min(height[left], height[i]) - height[bottom];
            water += width * h;
        }
        st.push(i);
    }
    return water;
}

