    stack<int> out;

   public:
    void push(int x) {
        in.push(x);
    }
    int pop() {
        shift();
        int x = out.top();
        out.pop();
        return x;
    }
    int peek() {
        shift();
        return out.top();
    }
    bool empty() {
        return in.empty() && out.empty();
    }

