    };
    auto add = [&](int x) {
        if (low.empty() || x <= *prev(low.end()))
            low.insert(x);
        else
            high.insert(x);
        balance();
    };
    auto remove = [&](int x) {
        auto it = low.find(x);
        if (it != low.end())
            low.erase(it);
        else {
            it = high.find(x);
            high.erase(it);
        }
        balance();
    };
    vector<double> ans;
    for (int i = 0; i < nums.size(); i++) {
        add(nums[i]);
        if (i >= k) remove(nums[i - k]);
        if (i >= k - 1) {
            if (low.size() == high.size()) {
                ans.push_back(((double)*prev(low.end()) + *high.begin()) / 2.0);
            } else {
                ans.push_back(*prev(low.end()));
            }
        }
    }
    return ans;
}

vector<int> mergeKSortedArrays(vector<vector<int>>& arr) {
    using T = tuple<int, int, int>;
    priority_queue<T, vector<T>, greater<T>> pq;
    for (int i = 0; i < arr.size(); i++) {
        if (!arr[i].empty()) pq.push({arr[i][0], i, 0});
    }
    vector<int> ans;
    while (!pq.empty()) {
        auto [val, row, col] = pq.top();
        pq.pop();
        ans.push_back(val);
        if (col + 1 < arr[row].size()) {
            pq.push({arr[row][col + 1], row, col + 1});
        }
    }
    return ans;
}

int minMeetingRooms(vector<vector<int>>& intervals) {
    sort(intervals.begin(), intervals.end());
    priority_queue<int, vector<int>, greater<int>> pq;
    for (auto& interval : intervals) {
        int start = interval[0];
        int end = interval[1];
        if (!pq.empty() && pq.top() <= start) {
            pq.pop();
        }
        pq.push(end);
    }
    return pq.size();
}

int leastInterval(vector<char>& tasks, int n) {
    vector<int> freq(26, 0);
    for (char c : tasks) freq[c - 'A']++;
    priority_queue<int> pq;
    for (int f : freq) {
        if (f > 0) pq.push(f);
    }
    int time = 0;
    while (!pq.empty()) {
        vector<int> used;
        for (int i = 0; i <= n; i++) {
            if (!pq.empty()) {
                int f = pq.top();
                pq.pop();
                f--;
                if (f > 0) used.push_back(f);
            }
            time++;
            if (pq.empty() && used.empty()) break;
        }
        for (int f : used) pq.push(f);
    }
    return time;
}

long long minCostRopes(vector<int>& ropes) {
    priority_queue<long long, vector<long long>, greater<long long>> pq;
    for (int rope : ropes) pq.push(rope);
    long long cost = 0;
    while (pq.size() > 1) {
        long long a = pq.top();
        pq.pop();
        long long b = pq.top();
        pq.pop();
        long long sum = a + b;
        cost += sum;
        pq.push(sum);
    }
    return cost;
}

struct HuffmanNode {
    char ch;
    int freq;
    HuffmanNode* left;
    HuffmanNode* right;
    HuffmanNode(char ch, int freq) : ch(ch), freq(freq), left(nullptr), right(nullptr) {}
};
struct CompareHuffman {
    bool operator()(HuffmanNode* a, HuffmanNode* b) {
        return a->freq > b->freq;
    }
};
HuffmanNode* buildHuffman(vector<pair<char, int>>& freq) {
    priority_queue<HuffmanNode*, vector<HuffmanNode*>, CompareHuffman> pq;
    for (auto& [ch, f] : freq) pq.push(new HuffmanNode(ch, f));
    while (pq.size() > 1) {
        HuffmanNode* a = pq.top();
        pq.pop();
        HuffmanNode* b = pq.top();
        pq.pop();
        HuffmanNode* parent = new HuffmanNode('\0', a->freq + b->freq);
        parent->left = a;
        parent->right = b;
        pq.push(parent);
    }
    return pq.top();
}

vector<vector<int>> kSmallestPairs(vector<int>& nums1, vector<int>& nums2, int k) {
    if (nums1.empty() || nums2.empty() || k <= 0) return {};
    using T = tuple<long long, int, int>;
    priority_queue<T, vector<T>, greater<T>> pq;
    int n = min(static_cast<int>(nums1.size()), k);
    for (int i = 0; i < n; i++) {
        pq.push({static_cast<long long>(nums1[i]) + nums2[0], i, 0});
    }
    vector<vector<int>> ans;
    while (k-- > 0 && !pq.empty()) {
        auto [sum, i, j] = pq.top();
        pq.pop();
        ans.push_back({nums1[i], nums2[j]});
        if (j + 1 < static_cast<int>(nums2.size())) {
            pq.push({static_cast<long long>(nums1[i]) + nums2[j + 1], i, j + 1});
        }
    }
    return ans;
}

