uint64_t hashState(const vector<int>& state) {
    uint64_t h = 0;
    for (int i = 0; i < static_cast<int>(state.size()); i++) {
        uint64_t token = (static_cast<uint64_t>(i) << 32) ^ static_cast<uint64_t>(static_cast<uint32_t>(state[i]));
        h ^= splitmix64(token);
    }
    return h;
}

vector<int> twoSum(vector<int>& nums, int target) {
    if (nums.size() < 2) return {};
    int l = 0;
    int r = static_cast<int>(nums.size()) - 1;
    while (l < r) {
        long long sum = 1LL * nums[l] + nums[r];
        if (sum == target) return {l, r};
        if (sum < target)
            l++;
        else
            r--;
    }
    return {};
}

vector<vector<int>> threeSum(vector<int>& nums) {
    sort(nums.begin(), nums.end());
    vector<vector<int>> ans;
    int n = nums.size();
    for (int i = 0; i < n - 2; i++) {
        if (i > 0 && nums[i] == nums[i - 1]) continue;
        int l = i + 1;
        int r = n - 1;
        while (l < r) {
            long long sum = 1LL * nums[i] + nums[l] + nums[r];
            if (sum == 0) {
                ans.push_back({nums[i], nums[l], nums[r]});
                int x = nums[l];
                int y = nums[r];
                while (l < r && nums[l] == x) l++;
                while (l < r && nums[r] == y) r--;
            } else if (sum < 0)
                l++;
            else
                r--;
        }
    }
    return ans;
}

vector<vector<int>> fourSum(vector<int>& nums, long long target) {
    sort(nums.begin(), nums.end());
    vector<vector<int>> ans;
    int n = nums.size();
    for (int i = 0; i < n - 3; i++) {
        if (i > 0 && nums[i] == nums[i - 1]) continue;
        for (int j = i + 1; j < n - 2; j++) {
            if (j > i + 1 && nums[j] == nums[j - 1]) continue;
            int l = j + 1;
            int r = n - 1;
            while (l < r) {
                long long sum = 1LL * nums[i] + nums[j] + nums[l] + nums[r];
                if (sum == target) {
                    ans.push_back({nums[i], nums[j], nums[l], nums[r]});
                    int x = nums[l];
                    int y = nums[r];
                    while (l < r && nums[l] == x) l++;
                    while (l < r && nums[r] == y) r--;
                } else if (sum < target)
                    l++;
                else
                    r--;
            }
        }
    }
    return ans;
}

int lengthOfLongestSubstring(string s) {
    vector<int> last(256, -1);
    int l = 0;
    int ans = 0;
    for (int r = 0; r < static_cast<int>(s.size()); r++) {
        unsigned char ch = static_cast<unsigned char>(s[r]);
        if (last[ch] >= l) l = last[ch] + 1;
        last[ch] = r;
        ans = max(ans, r - l + 1);
    }
    return ans;
}

int longestKDistinct(string s, int k) {
