    for (int r = 0; r < static_cast<int>(s.size()); r++) {
        freq[s[r]]++;
        while (static_cast<int>(freq.size()) > k) {
            freq[s[l]]--;
            if (freq[s[l]] == 0) freq.erase(s[l]);
            l++;
        }
        ans = max(ans, r - l + 1);
    }
