string minWindow(string s, string t) {
    if (t.empty() || s.empty() || t.size() > s.size()) return "";
    vector<int> need(256, 0);
    for (char c : t) need[static_cast<unsigned char>(c)]++;
    int required = static_cast<int>(t.size());
    int l = 0;
    int bestLen = INT_MAX;
    int bestL = 0;
    for (int r = 0; r < static_cast<int>(s.size()); r++) {
        unsigned char right = static_cast<unsigned char>(s[r]);
        if (need[right] > 0) required--;
        need[right]--;
        while (required == 0) {
            if (r - l + 1 < bestLen) {
                bestLen = r - l + 1;
                bestL = l;
            }
            unsigned char left = static_cast<unsigned char>(s[l]);
            need[left]++;
            if (need[left] > 0) required++;
            l++;
        }
    }
    return bestLen == INT_MAX ? "" : s.substr(bestL, bestLen);
}

int characterReplacement(string s, int k) {
    vector<int> freq(26, 0);
    int l = 0;
    int maxFreq = 0;
    int ans = 0;
    for (int r = 0; r < s.size(); r++) {
        freq[s[r] - 'A']++;
        maxFreq = max(maxFreq, freq[s[r] - 'A']);
        while ((r - l + 1) - maxFreq > k) {
            freq[s[l] - 'A']--;
            l++;
        }
        ans = max(ans, r - l + 1);
    }
    return ans;
}

bool checkInclusion(string s1, string s2) {
    if (s1.size() > s2.size()) return false;
    vector<int> need(26, 0);
    vector<int> have(26, 0);
    for (char c : s1) need[c - 'a']++;
    int k = s1.size();
    for (int i = 0; i < s2.size(); i++) {
        have[s2[i] - 'a']++;
        if (i >= k) have[s2[i - k] - 'a']--;
        if (have == need) return true;
    }
    return false;
}

vector<int> findAnagrams(string s, string p) {
    vector<int> need(26, 0);
    vector<int> have(26, 0);
    for (char c : p) need[c - 'a']++;
    vector<int> ans;
    int k = p.size();
    for (int i = 0; i < s.size(); i++) {
        have[s[i] - 'a']++;
        if (i >= k) have[s[i - k] - 'a']--;
        if (i >= k - 1 && have == need) ans.push_back(i - k + 1);
    }
    return ans;
}

int maxArea(vector<int>& height) {
    if (height.size() < 2) return 0;
    int l = 0;
    int r = static_cast<int>(height.size()) - 1;
    int ans = 0;
    while (l < r) {
        int area = min(height[l], height[r]) * (r - l);
        ans = max(ans, area);
        if (height[l] < height[r])
            l++;
        else
            r--;
    }
    return ans;
}

int trap(vector<int>& height) {
    if (height.size() < 3) return 0;
    int l = 0;
    int r = static_cast<int>(height.size()) - 1;
    int leftMax = 0;
    int rightMax = 0;
    int ans = 0;
    while (l < r) {
        if (height[l] <= height[r]) {
            if (height[l] >= leftMax)
                leftMax = height[l];
            else
                ans += leftMax - height[l];
            l++;
        } else {
            if (height[r] >= rightMax)
                rightMax = height[r];
            else
                ans += rightMax - height[r];
            r--;
        }
    }
    return ans;
}

long long numSubarrayProductLessThanK(vector<int>& nums, int k) {
