    for (int r = 0; r < static_cast<int>(nums.size()); r++) {
        product *= nums[r];
        while (product >= k) product /= nums[l++];
        ans += r - l + 1;
    }
    return ans;
}

long long countAtMostK(vector<int>& nums, long long k) {
