    freq[0] = 1;
    long long sum = 0;
    long long ans = 0;
    for (int x : nums) {
        sum += x;
        auto it = freq.find(sum - k);
        if (it != freq.end()) ans += it->second;
        freq[sum]++;
    }
    return ans;
}

int longestSubarraySumK(vector<int>& arr, long long k) {
