struct PairHash {
    size_t operator()(const pair<int, int>& p) const {
        size_t h1 = hash<int>{}(p.first);
        size_t h2 = hash<int>{}(p.second);
        return h1 ^ (h2 + 0x9e3779b97f4a7c15ULL + (h1 << 6) + (h1 >> 2));
    }
};
long long countEqual012(vector<int>& arr) {
    unordered_map<pair<int, int>, long long, PairHash> freq;
    int c0 = 0, c1 = 0, c2 = 0;
    long long ans = 0;
    freq[{0, 0}] = 1;
    for (int x : arr) {
        if (x == 0)
            c0++;
        else if (x == 1)
            c1++;
        else if (x == 2)
            c2++;
        else
            continue;
        pair<int, int> key = {c0 - c1, c1 - c2};
        ans += freq[key];
        freq[key]++;
    }
    return ans;
}

vector<long long> rangeAddition(int n, vector<vector<int>>& updates) {
    vector<long long> diff(n + 1, 0);
    for (auto& q : updates) {
        int l = q[0];
        int r = q[1];
        int x = q[2];
        diff[l] += x;
        if (r + 1 < n) diff[r + 1] -= x;
    }
    vector<long long> arr(n);
    long long curr = 0;
    for (int i = 0; i < n; i++) {
        curr += diff[i];
        arr[i] = curr;
    }
    return arr;
}

