    for (int i = 0; i < n; i++) {
        curr += diff[i];
        ans[i] = curr;
    }
    return ans;
}

vector<vector<long long>> buildPrefix(vector<vector<int>>& mat) {
    if (mat.empty() || mat[0].empty()) return {{0}};
    int n = static_cast<int>(mat.size());
    int m = static_cast<int>(mat[0].size());
    vector<vector<long long>> pref(n + 1, vector<long long>(m + 1, 0));
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            pref[i][j] = mat[i - 1][j - 1] + pref[i - 1][j] + pref[i][j - 1] - pref[i - 1][j - 1];
        }
    }
    return pref;
}
long long query(vector<vector<long long>>& pref, int r1, int c1, int r2, int c2) {
    r1++;
    c1++;
    r2++;
    c2++;
    return pref[r2][c2] - pref[r1 - 1][c2] - pref[r2][c1 - 1] + pref[r1 - 1][c1 - 1];
}

vector<vector<long long>> rectangleUpdates(int n, int m, vector<vector<int>>& queries) {
    vector<vector<long long>> diff(n + 1, vector<long long>(m + 1, 0));
    for (auto& q : queries) {
        int r1 = q[0];
        int c1 = q[1];
        int r2 = q[2];
        int c2 = q[3];
        int val = q[4];
        diff[r1][c1] += val;
        if (r2 + 1 < n) diff[r2 + 1][c1] -= val;
        if (c2 + 1 < m) diff[r1][c2 + 1] -= val;
        if (r2 + 1 < n && c2 + 1 < m) diff[r2 + 1][c2 + 1] += val;
    }
    vector<vector<long long>> ans(n, vector<long long>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (i > 0) diff[i][j] += diff[i - 1][j];
            if (j > 0) diff[i][j] += diff[i][j - 1];
            if (i > 0 && j > 0) diff[i][j] -= diff[i - 1][j - 1];
            ans[i][j] = diff[i][j];
        }
    }
    return ans;
}

