long long maxSumAtMostK(vector<int>& arr, int k) {
    if (arr.empty() || k <= 0) return 0;
    int n = static_cast<int>(arr.size());
    vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + arr[i];
    deque<int> dq;
    dq.push_back(0);
    long long ans = LLONG_MIN;
    for (int i = 1; i <= n; i++) {
        while (!dq.empty() && dq.front() < i - k) dq.pop_front();
        if (!dq.empty()) ans = max(ans, pref[i] - pref[dq.front()]);
        while (!dq.empty() && pref[dq.back()] >= pref[i]) dq.pop_back();
        dq.push_back(i);
    }
    return ans;
}

long long maxSumRangeLength(vector<int>& arr, int L, int R) {
    int n = arr.size();
    vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + arr[i];
    deque<int> dq;
    long long ans = LLONG_MIN;
    for (int i = L; i <= n; i++) {
        int add = i - L;
        while (!dq.empty() && pref[dq.back()] >= pref[add]) dq.pop_back();
        dq.push_back(add);
        while (!dq.empty() && dq.front() < i - R) dq.pop_front();
        ans = max(ans, pref[i] - pref[dq.front()]);
    }
    return ans;
}

