    if (start == s.size()) {
        ans.push_back(curr);
        return;
    }
    for (int end = start; end < s.size(); end++) {
        if (!isPalindrome(s, start, end)) continue;
        curr.push_back(s.substr(start, end - start + 1));
        solve(end + 1, s, curr, ans);
        curr.pop_back();
    }
}
