bool solve(vector<vector<char>>& board) {
    for (int r = 0; r < 9; r++) {
        for (int c = 0; c < 9; c++) {
            if (board[r][c] != '.') continue;
            for (char d = '1'; d <= '9'; d++) {
                bool ok = true;
                for (int i = 0; i < 9; i++) {
                    if (board[r][i] == d || board[i][c] == d) {
                        ok = false;
                        break;
                    }
                }
                int sr = (r / 3) * 3;
                int sc = (c / 3) * 3;
                for (int i = sr; i < sr + 3 && ok; i++) {
                    for (int j = sc; j < sc + 3; j++) {
                        if (board[i][j] == d) {
                            ok = false;
                            break;
                        }
                    }
                }
                if (!ok) continue;
                board[r][c] = d;
                if (solve(board)) return true;
                board[r][c] = '.';
            }
            return false;
        }
    }
    return true;
}

void solve(int r, int c, vector<vector<int>>& maze, vector<vector<int>>& vis, string& path, vector<string>& ans) {
    int n = static_cast<int>(maze.size());
    int m = static_cast<int>(maze[0].size());
    if (r == n - 1 && c == m - 1) {
        ans.push_back(path);
        return;
    }
    int dr[] = {1, 0, 0, -1};
    int dc[] = {0, -1, 1, 0};
    char dir[] = {'D', 'L', 'R', 'U'};
    for (int k = 0; k < 4; k++) {
        int nr = r + dr[k];
        int nc = c + dc[k];
        if (nr >= 0 && nr < n && nc >= 0 && nc < m && maze[nr][nc] && !vis[nr][nc]) {
            vis[nr][nc] = 1;
            path.push_back(dir[k]);
            solve(nr, nc, maze, vis, path, ans);
            path.pop_back();
            vis[nr][nc] = 0;
        }
    }
}
vector<string> ratInMaze(vector<vector<int>>& maze) {
    int n = static_cast<int>(maze.size());
    if (n == 0) return {};
    int m = static_cast<int>(maze[0].size());
    vector<string> ans;
    if (m == 0 || !maze[0][0] || !maze[n - 1][m - 1]) return ans;
    vector<vector<int>> vis(n, vector<int>(m, 0));
    string path;
    vis[0][0] = 1;
    solve(0, 0, maze, vis, path, ans);
    return ans;
}

bool dfs(int r, int c, int idx, vector<vector<char>>& board, const string& word) {
    if (idx == static_cast<int>(word.size())) return true;
    int n = static_cast<int>(board.size());
    int m = static_cast<int>(board[0].size());
    if (r < 0 || r >= n || c < 0 || c >= m || board[r][c] != word[idx]) return false;
    char temp = board[r][c];
    board[r][c] = '#';
    bool found = dfs(r + 1, c, idx + 1, board, word) || dfs(r - 1, c, idx + 1, board, word) ||
                 dfs(r, c + 1, idx + 1, board, word) || dfs(r, c - 1, idx + 1, board, word);
    board[r][c] = temp;
    return found;
}
bool exist(vector<vector<char>>& board, string word) {
    if (word.empty()) return true;
    if (board.empty() || board[0].empty()) return false;
    for (int i = 0; i < static_cast<int>(board.size()); i++) {
        for (int j = 0; j < static_cast<int>(board[0].size()); j++) {
            if (dfs(i, j, 0, board, word)) return true;
        }
    }
    return false;
}

bool solve(int node, int n, int k, vector<vector<int>>& graph, vector<int>& color) {
    if (node == n) return true;
    for (int c = 1; c <= k; c++) {
        bool safe = true;
        for (int v = 0; v < n; v++) {
            if (graph[node][v] && color[v] == c) {
                safe = false;
                break;
            }
        }
        if (!safe) continue;
        color[node] = c;
        if (solve(node + 1, n, k, graph, color)) return true;
        color[node] = 0;
    }
    return false;
}
bool graphColoring(vector<vector<int>>& graph, int k) {
    int n = graph.size();
    vector<int> color(n, 0);
    return solve(0, n, k, graph, color);
}

bool solve(int u, int count, vector<vector<int>>& graph, vector<bool>& used) {
    if (count == graph.size()) return true;
    for (int v = 0; v < graph.size(); v++) {
        if (graph[u][v] && !used[v]) {
            used[v] = true;
            if (solve(v, count + 1, graph, used)) return true;
            used[v] = false;
        }
    }
    return false;
}
bool hamiltonianPath(vector<vector<int>>& graph) {
    int n = graph.size();
    vector<bool> used(n, false);
    for (int start = 0; start < n; start++) {
        used[start] = true;
        if (solve(start, 1, graph, used)) return true;
        used[start] = false;
    }
    return false;
}

bool solve(int idx, vector<int>& arr, vector<int>& bucket, int target) {
    if (idx == static_cast<int>(arr.size())) return true;
    for (int i = 0; i < static_cast<int>(bucket.size()); i++) {
        if (bucket[i] + arr[idx] > target) continue;
        if (i > 0 && bucket[i] == bucket[i - 1]) continue;
        bucket[i] += arr[idx];
        if (solve(idx + 1, arr, bucket, target)) return true;
        bucket[i] -= arr[idx];
        if (bucket[i] == 0) break;
    }
    return false;
}
bool canPartitionKSubsets(vector<int>& arr, int k) {
    if (k <= 0) return false;
    long long sum = accumulate(arr.begin(), arr.end(), 0LL);
    if (sum % k != 0) return false;
    int target = static_cast<int>(sum / k);
    sort(arr.rbegin(), arr.rend());
    if (!arr.empty() && arr[0] > target) return false;
    vector<int> bucket(k, 0);
    return solve(0, arr, bucket, target);
}

class Solution {
   public:
    int ans = 0;
    int height(TreeNode* root) {
        if (root == nullptr) return 0;
        int left = height(root->left);
        int right = height(root->right);
        ans = max(ans, left + right);
        return 1 + max(left, right);
    }
    int diameterOfBinaryTree(TreeNode* root) {
        height(root);
        return ans;
    }
};

class Solution {
   public:
    int ans = INT_MIN;
    int solve(TreeNode* root) {
        if (root == nullptr) return 0;
        int left = max(0, solve(root->left));
        int right = max(0, solve(root->right));
        ans = max(ans, root->val + left + right);
        return root->val + max(left, right);
    }
    int maxPathSum(TreeNode* root) {
        solve(root);
        return ans;
    }
};

class Solution {
   public:
    int height(TreeNode* root) {
        if (root == nullptr) return 0;
        int left = height(root->left);
        if (left == -1) return -1;
        int right = height(root->right);
        if (right == -1) return -1;
        if (abs(left - right) > 1) return -1;
        return 1 + max(left, right);
    }
    bool isBalanced(TreeNode* root) {
        return height(root) != -1;
    }
};

TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
    if (root == nullptr || root == p || root == q) {
        return root;
    }
    TreeNode* left = lowestCommonAncestor(root->left, p, q);
    TreeNode* right = lowestCommonAncestor(root->right, p, q);
    if (left != nullptr && right != nullptr) {
        return root;
    }
    return left != nullptr ? left : right;
}

TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
    while (root != nullptr) {
        if (p->val < root->val && q->val < root->val) {
            root = root->left;
        } else if (p->val > root->val && q->val > root->val) {
            root = root->right;
        } else {
            return root;
        }
    }
    return nullptr;
}

class Solution {
    struct Info {
        bool isBST;
        int mn;
        int mx;
        int sum;
    };
    int ans = 0;
    Info solve(TreeNode* root) {
        if (root == nullptr) {
            return {true, INT_MAX, INT_MIN, 0};
        }
        Info left = solve(root->left);
        Info right = solve(root->right);
        if (left.isBST && right.isBST && left.mx < root->val && root->val < right.mn) {
            int sum = left.sum + right.sum + root->val;
            ans = max(ans, sum);
            return {true, min(left.mn, root->val), max(right.mx, root->val), sum};
        }
        return {false, 0, 0, 0};
    }

   public:
    int maxSumBST(TreeNode* root) {
        solve(root);
        return ans;
    }
};

class Codec {
   public:
    void serializeHelper(TreeNode* root, string& s) {
        if (root == nullptr) {
            s += "#,";
            return;
        }
        s += to_string(root->val);
        s += ",";
        serializeHelper(root->left, s);
        serializeHelper(root->right, s);
    }
    string serialize(TreeNode* root) {
        string s;
        serializeHelper(root, s);
        return s;
    }
    TreeNode* deserializeHelper(stringstream& ss) {
        string token;
        getline(ss, token, ',');
        if (token == "#") return nullptr;
        TreeNode* root = new TreeNode(stoi(token));
        root->left = deserializeHelper(ss);
        root->right = deserializeHelper(ss);
        return root;
    }
    TreeNode* deserialize(string data) {
        stringstream ss(data);
        return deserializeHelper(ss);
    }
};

class Solution {
    unordered_map<int, int> pos;
    int preIndex = 0;
    TreeNode* build(vector<int>& preorder, int l, int r) {
        if (l > r) return nullptr;
        int value = preorder[preIndex++];
        TreeNode* root = new TreeNode(value);
        int mid = pos[value];
        root->left = build(preorder, l, mid - 1);
        root->right = build(preorder, mid + 1, r);
        return root;
    }

   public:
    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        for (int i = 0; i < inorder.size(); i++) {
            pos[inorder[i]] = i;
        }
        return build(preorder, 0, inorder.size() - 1);
    }
};

class Solution {
    unordered_map<int, int> pos;
    int postIndex;
    TreeNode* build(vector<int>& postorder, int l, int r) {
        if (l > r) return nullptr;
        int value = postorder[postIndex--];
        TreeNode* root = new TreeNode(value);
        int mid = pos[value];
        root->right = build(postorder, mid + 1, r);
        root->left = build(postorder, l, mid - 1);
        return root;
    }

   public:
    TreeNode* buildTree(vector<int>& inorder, vector<int>& postorder) {
        for (int i = 0; i < inorder.size(); i++) {
            pos[inorder[i]] = i;
        }
        postIndex = postorder.size() - 1;
        return build(postorder, 0, inorder.size() - 1);
    }
};

struct BinaryLiftingLCA {
    int log = 1;
    vector<int> depth;
    vector<vector<int>> up;
    const vector<vector<int>>& adj;

    BinaryLiftingLCA(const vector<vector<int>>& graph, int root = 0) : depth(graph.size(), 0), adj(graph) {
        int n = static_cast<int>(graph.size());
        while ((1LL << log) <= max(1, n)) {
            ++log;
        }
        up.assign(n, vector<int>(log, -1));
        if (n > 0) {
            dfs(root, -1);
        }
    }

    void dfs(int u, int parent) {
        up[u][0] = parent;
        for (int j = 1; j < log; ++j) {
            int mid = up[u][j - 1];
            up[u][j] = (mid == -1 ? -1 : up[mid][j - 1]);
        }
        for (int v : adj[u]) {
            if (v == parent) continue;
            depth[v] = depth[u] + 1;
            dfs(v, u);
        }
    }

    int lca(int u, int v) const {
        if (depth[u] < depth[v]) {
            swap(u, v);
        }
        int diff = depth[u] - depth[v];
        for (int j = log - 1; j >= 0; --j) {
            if (diff & (1 << j)) {
                u = up[u][j];
            }
        }
        if (u == v) {
            return u;
        }
        for (int j = log - 1; j >= 0; --j) {
            if (up[u][j] != up[v][j]) {
                u = up[u][j];
                v = up[v][j];
            }
        }
        return up[u][0];
    }
};

int kthAncestor(int node, int k, const vector<vector<int>>& up) {
    if (node < 0 || node >= static_cast<int>(up.size()) || k < 0) {
        return -1;
    }
    int bit = 0;
    while (k > 0 && node != -1) {
        if (bit == static_cast<int>(up[node].size())) {
            return -1;
        }
        if (k & 1) {
            node = up[node][bit];
        }
        k >>= 1;
        ++bit;
    }
    return node;
}

vector<int> tin, tout;
