vector<vector<int>> dp;
void dfs(int u, int parent, vector<vector<int>>& adj) {
    // dp[u][0] = don't take u
    // dp[u][1] = take u
    dp[u][0] = 0;
    dp[u][1] = 1;
    for (int v : adj[u]) {
        if (v == parent) continue;
        dfs(v, u, adj);
        dp[u][0] += max(dp[v][0], dp[v][1]);
        dp[u][1] += dp[v][0];
    }
}

vector<vector<int>> dp;
void dfs(int u, int parent, vector<vector<int>>& adj) {
    // dp[u][0] = don't take u
    // dp[u][1] = take u
    dp[u][0] = 0;
    dp[u][1] = 1;
    for (int v : adj[u]) {
        if (v == parent) continue;
        dfs(v, u, adj);
        // u not selected
        // child must be selected
        dp[u][0] += dp[v][1];
        // u selected
        // child can be either
        dp[u][1] += min(dp[v][0], dp[v][1]);
    }
}

vector<int> subtreeSize;
vector<long long> distSum;

void dfs1(int u, int parent, int depth, const vector<vector<int>>& adj, int root) {
    subtreeSize[u] = 1;
    distSum[root] += depth;
    for (int v : adj[u]) {
        if (v == parent) continue;
        dfs1(v, u, depth + 1, adj, root);
        subtreeSize[u] += subtreeSize[v];
    }
}

void dfs2(int u, int parent, const vector<vector<int>>& adj, int n) {
    for (int v : adj[u]) {
        if (v == parent) continue;
        distSum[v] = distSum[u] + n - 2LL * subtreeSize[v];
        dfs2(v, u, adj, n);
    }
}

vector<long long> sumOfDistances(const vector<vector<int>>& adj, int root = 0) {
    int n = static_cast<int>(adj.size());
    if (n == 0) {
        return {};
    }
    subtreeSize.assign(n, 0);
    distSum.assign(n, 0);
    dfs1(root, -1, 0, adj, root);
    dfs2(root, -1, adj, n);
    return distSum;
}

bool hasPathSum(TreeNode* root, int targetSum) {
    if (root == nullptr) return false;
    if (root->left == nullptr && root->right == nullptr) {
        return targetSum == root->val;
    }
    targetSum -= root->val;
    return hasPathSum(root->left, targetSum) || hasPathSum(root->right, targetSum);
}

struct HeavyLightDecomposition {
    vector<int> parent;
    vector<int> depth;
    vector<int> heavy;
    vector<int> head;
    vector<int> pos;
    vector<int> subtreeSize;
    int currentPos = 0;
    const vector<vector<int>>& adj;

    HeavyLightDecomposition(const vector<vector<int>>& graph, int root = 0)
        : parent(graph.size(), -1),
          depth(graph.size(), 0),
          heavy(graph.size(), -1),
          head(graph.size(), 0),
          pos(graph.size(), 0),
          subtreeSize(graph.size(), 0),
          adj(graph) {
        if (!graph.empty()) {
            dfs(root, -1);
            decompose(root, root);
        }
    }

    int dfs(int u, int p) {
        parent[u] = p;
        subtreeSize[u] = 1;
        int maxSubtree = 0;
        for (int v : adj[u]) {
            if (v == p) continue;
            depth[v] = depth[u] + 1;
            int childSize = dfs(v, u);
            subtreeSize[u] += childSize;
            if (childSize > maxSubtree) {
                maxSubtree = childSize;
                heavy[u] = v;
            }
        }
        return subtreeSize[u];
    }

    void decompose(int u, int chainHead) {
        head[u] = chainHead;
        pos[u] = currentPos++;
        if (heavy[u] != -1) {
            decompose(heavy[u], chainHead);
        }
        for (int v : adj[u]) {
            if (v == parent[u] || v == heavy[u]) continue;
            decompose(v, v);
        }
    }
};

void flatten(TreeNode* root) {
    if (root == nullptr) return;
    TreeNode* curr = root;
    while (curr != nullptr) {
        if (curr->left != nullptr) {
            TreeNode* pred = curr->left;
            while (pred->right != nullptr) pred = pred->right;
            pred->right = curr->right;
            curr->right = curr->left;
            curr->left = nullptr;
        }
        curr = curr->right;
    }
}

TreeNode* deleteNode(TreeNode* root, int key) {
    if (root == nullptr) return nullptr;
    if (key < root->val) {
        root->left = deleteNode(root->left, key);
    } else if (key > root->val) {
        root->right = deleteNode(root->right, key);
    } else {
        // 0 or 1 child
        if (root->left == nullptr) return root->right;
        if (root->right == nullptr) return root->left;
        // 2 children
        TreeNode* succ = root->right;
        while (succ->left != nullptr) succ = succ->left;
        root->val = succ->val;
        root->right = deleteNode(root->right, succ->val);
    }
    return root;
}

bool isValidBST(TreeNode* root, long long low = LLONG_MIN, long long high = LLONG_MAX) {
    if (root == nullptr) return true;
    if (root->val <= low || root->val >= high) return false;
    return isValidBST(root->left, low, root->val) && isValidBST(root->right, root->val, high);
}

int kthSmallest(TreeNode* root, int k) {
    stack<TreeNode*> st;
    while (root != nullptr || !st.empty()) {
        while (root != nullptr) {
            st.push(root);
            root = root->left;
        }
        root = st.top();
        st.pop();
        k--;
        if (k == 0) return root->val;
        root = root->right;
    }
    return -1;
}

int kthLargest(TreeNode* root, int k) {
    stack<TreeNode*> st;
    while (root != nullptr || !st.empty()) {
        while (root != nullptr) {
            st.push(root);
            root = root->right;
        }
        root = st.top();
        st.pop();
        k--;
        if (k == 0) return root->val;
        root = root->left;
    }
    return -1;
}

