int rankOfKey(const Node* root, int key) {
    int rank = 0;
    while (root != nullptr) {
        if (key <= root->val) {
            root = root->left;
        } else {
            rank += 1 + getSize(root->left);
            root = root->right;
        }
    }
    return rank;
}

