int kthSmallest(Node* root, int k) {
    while (root != nullptr) {
        int leftSize = getSize(root->left);
        if (k == leftSize + 1) return root->val;
        if (k <= leftSize) {
            root = root->left;
        } else {
            k -= leftSize + 1;
            root = root->right;
        }
    }
    return -1;
}

void rangeSearch(TreeNode* root, int low, int high, vector<int>& ans) {
    if (root == nullptr) return;
    if (root->val > low) rangeSearch(root->left, low, high, ans);
    if (root->val >= low && root->val <= high) {
        ans.push_back(root->val);
    }
    if (root->val < high) rangeSearch(root->right, low, high, ans);
}

class BSTIterator {
    stack<TreeNode*> st;
    bool reverse;

    void pushPath(TreeNode* node) {
        while (node != nullptr) {
            st.push(node);
            node = reverse ? node->right : node->left;
        }
    }

   public:
    BSTIterator(TreeNode* root, bool isReverse) : reverse(isReverse) {
        pushPath(root);
    }

    bool hasNext() const {
        return !st.empty();
    }

    TreeNode* nextNode() {
        TreeNode* node = st.top();
        st.pop();
        if (reverse) {
            pushPath(node->left);
        } else {
            pushPath(node->right);
        }
        return node;
    }
};

bool findTarget(TreeNode* root, int k) {
    if (root == nullptr) {
        return false;
    }
    BSTIterator left(root, false);
    BSTIterator right(root, true);
    if (!left.hasNext() || !right.hasNext()) {
        return false;
    }
    TreeNode* lo = left.nextNode();
    TreeNode* hi = right.nextNode();
    while (lo != nullptr && hi != nullptr && lo != hi && lo->val <= hi->val) {
        long long sum = 1LL * lo->val + hi->val;
        if (sum == k) {
            return true;
        }
        if (sum < k) {
            if (!left.hasNext()) {
                break;
            }
            lo = left.nextNode();
        } else {
            if (!right.hasNext()) {
                break;
            }
            hi = right.nextNode();
        }
    }
    return false;
}

TreeNode* sortedArrayToBST(vector<int>& nums, int l, int r) {
    if (l > r) return nullptr;
    int mid = l + (r - l) / 2;
    TreeNode* root = new TreeNode(nums[mid]);
    root->left = sortedArrayToBST(nums, l, mid - 1);
    root->right = sortedArrayToBST(nums, mid + 1, r);
    return root;
}

void inorder(TreeNode* root, vector<int>& nums) {
    if (root == nullptr) return;
    inorder(root->left, nums);
    nums.push_back(root->val);
    inorder(root->right, nums);
}
TreeNode* build(vector<int>& nums, int l, int r) {
    if (l > r) return nullptr;
    int mid = l + (r - l) / 2;
    TreeNode* root = new TreeNode(nums[mid]);
    root->left = build(nums, l, mid - 1);
    root->right = build(nums, mid + 1, r);
    return root;
}
