    bool reverse;
    void pushAll(TreeNode* root) {
        while (root != nullptr) {
            st.push(root);
            if (reverse)
                root = root->right;
            else
                root = root->left;
        }
    }

   public:
    BSTIterator(TreeNode* root, bool isReverse) {
        reverse = isReverse;
        pushAll(root);
    }
    int next() {
        TreeNode* node = st.top();
        st.pop();
        if (reverse)
            pushAll(node->left);
        else
            pushAll(node->right);
        return node->val;
    }
};

