int countLessThan(const Node* root, long long x) {
    int ans = 0;
    while (root != nullptr) {
        if (x <= root->val) {
            root = root->left;
        } else {
            ans += 1 + getSize(root->left);
            root = root->right;
        }
    }
    return ans;
}

