    return countLessThan(root, static_cast<long long>(R) + 1) - countLessThan(root, static_cast<long long>(L));
}

void build(vector<int>& arr, vector<int>& tree, int node, int l, int r) {
    if (l == r) {
        tree[node] = arr[l];
        return;
    }
    int mid = l + (r - l) / 2;
    build(arr, tree, 2 * node, l, mid);
    build(arr, tree, 2 * node + 1, mid + 1, r);
    tree[node] = tree[2 * node] + tree[2 * node + 1];
}

int query(vector<int>& tree, int node, int l, int r, int ql, int qr) {
    if (qr < l || r < ql) return 0;
    if (ql <= l && r <= qr) return tree[node];
    int mid = l + (r - l) / 2;
    return query(tree, 2 * node, l, mid, ql, qr) + query(tree, 2 * node + 1, mid + 1, r, ql, qr);
}

void update(vector<int>& tree, int node, int l, int r, int idx, int val) {
    if (l == r) {
        tree[node] = val;
        return;
    }
    int mid = l + (r - l) / 2;
    if (idx <= mid) {
        update(tree, 2 * node, l, mid, idx, val);
    } else {
        update(tree, 2 * node + 1, mid + 1, r, idx, val);
    }
    tree[node] = tree[2 * node] + tree[2 * node + 1];
}

void push(vector<long long>& tree, vector<long long>& lazy, int node, int l, int r) {
    if (lazy[node] == 0) return;
    tree[node] += (r - l + 1) * lazy[node];
    if (l != r) {
        lazy[2 * node] += lazy[node];
        lazy[2 * node + 1] += lazy[node];
    }
    lazy[node] = 0;
}
void update(vector<long long>& tree, vector<long long>& lazy, int node, int l, int r, int ql, int qr, long long val) {
    push(tree, lazy, node, l, r);
    if (qr < l || r < ql) return;
    if (ql <= l && r <= qr) {
        lazy[node] += val;
        push(tree, lazy, node, l, r);
        return;
    }
    int mid = l + (r - l) / 2;
    update(tree, lazy, 2 * node, l, mid, ql, qr, val);
    update(tree, lazy, 2 * node + 1, mid + 1, r, ql, qr, val);
    tree[node] = tree[2 * node] + tree[2 * node + 1];
}
