int firstAtLeast(vector<int>& tree, int node, int l, int r, int ql, int x) {
    if (r < ql || tree[node] < x) return -1;
    if (l == r) return l;
    int mid = l + (r - l) / 2;
    int left = firstAtLeast(tree, 2 * node, l, mid, ql, x);
    if (left != -1) return left;
    return firstAtLeast(tree, 2 * node + 1, mid + 1, r, ql, x);
}

int kthOne(const vector<int>& tree, int node, int l, int r, int k) {
    if (k <= 0 || tree[node] < k) return -1;
    if (l == r) return l;
    int mid = l + (r - l) / 2;
    if (tree[2 * node] >= k) {
        return kthOne(tree, 2 * node, l, mid, k);
    }
    return kthOne(tree, 2 * node + 1, mid + 1, r, k - tree[2 * node]);
}

