bool remove(TrieNode* root, string word, int depth = 0) {
    if (root == nullptr) return false;
    if (depth == word.size()) {
        if (!root->isEnd) return false;
        root->isEnd = false;
        return true;
    }
    int x = word[depth] - 'a';
    if (root->child[x] == nullptr) return false;
    bool removed = remove(root->child[x], word, depth + 1);
    if (!removed) return false;
    TrieNode* child = root->child[x];
    bool empty = !child->isEnd;
    for (int i = 0; i < 26; i++) {
        if (child->child[i] != nullptr) {
            empty = false;
            break;
        }
    }
    if (empty) {
        delete child;
        root->child[x] = nullptr;
    }
    return true;
}

void dfs(TrieNode* node, string& current, vector<string>& ans) {
    if (node == nullptr) return;
    if (node->isEnd) ans.push_back(current);
    for (int i = 0; i < 26; i++) {
        if (node->child[i] != nullptr) {
            current.push_back('a' + i);
            dfs(node->child[i], current, ans);
            current.pop_back();
        }
    }
}
