        if (node->child[x] == nullptr) return false;
        return search(node->child[x], word, i + 1);
    }
    for (int x = 0; x < 26; x++) {
        if (node->child[x] && search(node->child[x], word, i + 1)) {
            return true;
        }
    }
    return false;
}

