vector<long long> buildFenwick(vector<long long>& arr) {
    int n = arr.size() - 1;
    vector<long long> bit = arr;
    for (int i = 1; i <= n; i++) {
        int parent = i + (i & -i);
        if (parent <= n) bit[parent] += bit[i];
    }
    return bit;
}

long long prefixSum(const vector<long long>& bit, int idx) {
    idx = min(idx, static_cast<int>(bit.size()) - 1);
    long long sum = 0;
    while (idx > 0) {
        sum += bit[idx];
        idx -= idx & -idx;
    }
    return sum;
}

int kthSmallest(const vector<long long>& bit, int n, long long k) {
    if (n <= 0 || k <= 0 || k > prefixSum(bit, n)) {
        return -1;
    }
    int idx = 0;
    int pw = 1;
    while ((pw << 1) <= n) pw <<= 1;
    for (int step = pw; step > 0; step >>= 1) {
        int next = idx + step;
        if (next <= n && bit[next] < k) {
            idx = next;
            k -= bit[next];
        }
    }
    return idx + 1;
}

long long countInversions(vector<int>& arr) {
    int n = arr.size();
    vector<int> temp = arr;
    sort(temp.begin(), temp.end());
    temp.erase(unique(temp.begin(), temp.end()), temp.end());
    int m = temp.size();
    vector<long long> bit(m + 1, 0);
    auto update = [&](int idx) {
        while (idx <= m) {
            bit[idx]++;
            idx += idx & -idx;
        }
