    long long ans = 0;
    for (int i = n - 1; i >= 0; i--) {
        int rank = lower_bound(temp.begin(), temp.end(), arr[i]) - temp.begin() + 1;
        ans += query(rank - 1);
        update(rank);
    }
    return ans;
}

