    void add(int idx, int delta) {
        while (idx <= n) {
            bit[idx] += delta;
            idx += idx & -idx;
        }
    }

    int prefix(int idx) const {
        idx = max(0, min(idx, n));
        int sum = 0;
        while (idx > 0) {
            sum += bit[idx];
            idx -= idx & -idx;
        }
        return sum;
    }

   public:
    explicit OrderStatistic(int n) : n(n), bit(n + 1, 0), freq(n + 1, 0) {}

    void insert(int x) {
        if (x < 1 || x > n) return;
        ++freq[x];
        add(x, 1);
    }

    bool erase(int x) {
        if (x < 1 || x > n || freq[x] == 0) {
            return false;
        }
        --freq[x];
        add(x, -1);
        return true;
    }

    int countLessEqual(int x) const {
        return prefix(x);
    }

    int kth(int k) const {
        int total = prefix(n);
        if (k <= 0 || k > total) {
            return -1;
        }
        int idx = 0;
        int step = 1;
        while ((step << 1) <= n) step <<= 1;
        for (; step > 0; step >>= 1) {
            int next = idx + step;
            if (next <= n && bit[next] < k) {
                idx = next;
                k -= bit[next];
            }
        }
        return idx + 1;
    }
};

struct SmallerCounts {
    vector<int> left;
    vector<int> right;
};

SmallerCounts countSmallerOnBothSides(const vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    vector<int> vals = arr;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int m = static_cast<int>(vals.size());
    vector<int> bit(m + 1, 0);

    auto update = [&](int idx) {
        while (idx <= m) {
            bit[idx]++;
            idx += idx & -idx;
        }
    };
    auto query = [&](int idx) {
        int sum = 0;
        while (idx > 0) {
            sum += bit[idx];
            idx -= idx & -idx;
        }
        return sum;
    };

    vector<int> left(n), right(n);
    for (int i = 0; i < n; ++i) {
        int rank = static_cast<int>(lower_bound(vals.begin(), vals.end(), arr[i]) - vals.begin()) + 1;
        left[i] = query(rank - 1);
        update(rank);
    }

    fill(bit.begin(), bit.end(), 0);
    for (int i = n - 1; i >= 0; --i) {
        int rank = static_cast<int>(lower_bound(vals.begin(), vals.end(), arr[i]) - vals.begin()) + 1;
        right[i] = query(rank - 1);
        update(rank);
    }

    return {left, right};
}

class Fenwick {
    vector<long long> bit;

   public:
    explicit Fenwick(int n) : bit(n + 1, 0) {}

    void update(int idx, long long delta) {
        while (idx < static_cast<int>(bit.size())) {
            bit[idx] += delta;
            idx += idx & -idx;
        }
    }

    long long query(int idx) const {
        long long sum = 0;
        while (idx > 0) {
            sum += bit[idx];
            idx -= idx & -idx;
        }
        return sum;
    }
};

long long countIncreasing(const vector<int>& arr, int K) {
    if (K <= 0 || arr.empty()) {
        return 0;
    }
    vector<int> vals = arr;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int m = static_cast<int>(vals.size());

    vector<Fenwick> bits;
    bits.reserve(K + 1);
    bits.emplace_back(0);
    for (int len = 1; len <= K; ++len) {
        bits.emplace_back(m);
    }

    for (int x : arr) {
        int rank = static_cast<int>(lower_bound(vals.begin(), vals.end(), x) - vals.begin()) + 1;
        for (int len = K; len >= 2; --len) {
            long long ways = bits[len - 1].query(rank - 1);
            bits[len].update(rank, ways);
        }
        bits[1].update(rank, 1);
    }
    return bits[K].query(m);
}

