        }
        return sum;
    }
};

vector<long long> prefixInversions(const vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    vector<int> vals = arr;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int m = static_cast<int>(vals.size());

    Fenwick bit(m);
    vector<long long> ans;
    ans.reserve(n);
    long long inversions = 0;
    for (int i = 0; i < n; ++i) {
        int rank = static_cast<int>(lower_bound(vals.begin(), vals.end(), arr[i]) - vals.begin()) + 1;
        long long smallerOrEqual = bit.query(rank);
        inversions += i - smallerOrEqual;
        ans.push_back(inversions);
        bit.update(rank, 1);
    }
    return ans;
}

class DSU {
    vector<int> parent, sz;

   public:
    DSU(int n) {
        parent.resize(n);
        sz.assign(n, 1);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] == x) return x;
        return parent[x] = find(parent[x]);
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
    }
    bool same(int a, int b) {
        return find(a) == find(b);
    }
};

bool hasCycle(int n, vector<vector<int>>& edges) {
    DSU dsu(n);
    for (auto& edge : edges) {
        int u = edge[0];
        int v = edge[1];
        if (dsu.find(u) == dsu.find(v)) return true;
        dsu.unite(u, v);
    }
    return false;
}

int countComponents(int n, vector<vector<int>>& edges) {
    DSU dsu(n);
    int components = n;
    for (auto& edge : edges) {
        int u = edge[0];
        int v = edge[1];
        if (dsu.find(u) != dsu.find(v)) {
            dsu.unite(u, v);
            components--;
        }
    }
    return components;
}

