int largestComponent(int n, const vector<vector<int>>& edges) {
    if (n == 0) return 0;
    DSU dsu(n);
    int best = 1;
    for (const auto& edge : edges) {
        dsu.unite(edge[0], edge[1]);
        best = max(best, dsu.componentSize(edge[0]));
    }
    return best;
}

vector<int> redundantConnection(vector<vector<int>>& edges) {
