struct Edge {
    int u, v;
    long long w;
};

long long kruskal(int n, vector<Edge> edges) {
    if (n == 0) return 0;
    sort(edges.begin(), edges.end(), [](const Edge& a, const Edge& b) { return a.w < b.w; });

    DSU dsu(n);
    long long cost = 0;
    int used = 0;
    for (const auto& e : edges) {
        if (!dsu.unite(e.u, e.v)) continue;
        cost += e.w;
        if (++used == n - 1) break;
    }
    return used == n - 1 ? cost : -1;
}

vector<vector<string>> accountsMerge(vector<vector<string>>& accounts) {
    int n = accounts.size();
    DSU dsu(n);
    unordered_map<string, int> owner;
    for (int i = 0; i < n; i++) {
        for (int j = 1; j < accounts[i].size(); j++) {
            string email = accounts[i][j];
            if (owner.count(email))
                dsu.unite(i, owner[email]);
            else
                owner[email] = i;
        }
    }
    unordered_map<int, vector<string>> groups;
    for (auto& [email, id] : owner) {
        groups[dsu.find(id)].push_back(email);
    }
    vector<vector<string>> ans;
    for (auto& [root, emails] : groups) {
        sort(emails.begin(), emails.end());
        vector<string> cur;
        cur.push_back(accounts[root][0]);
        for (auto& email : emails) cur.push_back(email);
        ans.push_back(cur);
    }
    return ans;
}

int removeStones(vector<vector<int>>& stones) {
    int n = stones.size();
    DSU dsu(n);
    unordered_map<int, int> row;
    unordered_map<int, int> col;
    for (int i = 0; i < n; i++) {
        int r = stones[i][0];
        int c = stones[i][1];
        if (row.count(r))
            dsu.unite(i, row[r]);
        else
            row[r] = i;
        if (col.count(c))
            dsu.unite(i, col[c]);
        else
            col[c] = i;
    }
    unordered_set<int> components;
    for (int i = 0; i < n; i++) components.insert(dsu.find(i));
    return n - components.size();
}

vector<int> numIslands2(int n, int m, vector<vector<int>>& positions) {
    DSU dsu(n * m);
    vector<int> land(n * m, 0);
    vector<int> ans;
    int islands = 0;
    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};
    for (auto& p : positions) {
        int x = p[0];
        int y = p[1];
        int id = x * m + y;
        if (land[id]) {
            ans.push_back(islands);
            continue;
        }
        land[id] = 1;
        islands++;
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
            int nid = nx * m + ny;
            if (!land[nid]) continue;
            if (dsu.find(id) != dsu.find(nid)) {
                dsu.unite(id, nid);
                islands--;
            }
        }
        ans.push_back(islands);
    }
    return ans;
}

class WeightedDSU {
    vector<int> parent;
    vector<long long> weight;

   public:
    WeightedDSU(int n) {
        parent.resize(n);
        weight.assign(n, 0);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] == x) return x;
        int p = parent[x];
        parent[x] = find(parent[x]);
        weight[x] += weight[p];
        return parent[x];
    }
    void unite(int a, int b, long long diff) {
        // value[b] - value[a] = diff
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        parent[rb] = ra;
        weight[rb] = weight[a] + diff - weight[b];
    }
    long long difference(int a, int b) {
        if (find(a) != find(b)) return LLONG_MAX;
        // value[b] - value[a]
        return weight[b] - weight[a];
    }
};

class RollbackDSU {
    vector<int> parent, sz;
    struct Change {
        int b;
        int sizeA;
    };
    vector<Change> history;

   public:
    RollbackDSU(int n) {
        parent.resize(n);
        sz.assign(n, 1);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        while (x != parent[x]) x = parent[x];
        return x;
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) {
            history.push_back({-1, -1});
            return;
        }
        if (sz[a] < sz[b]) swap(a, b);
        history.push_back({b, sz[a]});
        parent[b] = a;
        sz[a] += sz[b];
    }
    int snapshot() {
        return history.size();
    }
    void rollback(int snap) {
        while (history.size() > snap) {
            auto [b, sizeA] = history.back();
            history.pop_back();
            if (b == -1) continue;
            int a = parent[b];
            parent[b] = b;
            sz[a] = sizeA;
        }
    }
};

#include <bits/stdc++.h>
using namespace std;

class RollbackDSU {
    struct Change {
        int child;
        int sizeOfParent;
    };

    vector<int> parent, size_;
    vector<Change> history;

   public:
    explicit RollbackDSU(int n) : parent(n), size_(n, 1) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        while (x != parent[x]) x = parent[x];
        return x;
    }

    bool same(int a, int b) {
        return find(a) == find(b);
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) {
            history.push_back({-1, -1});
            return;
        }
        if (size_[a] < size_[b]) swap(a, b);
        history.push_back({b, size_[a]});
        parent[b] = a;
        size_[a] += size_[b];
    }

    int snapshot() const {
        return static_cast<int>(history.size());
    }

    void rollback(int snapshot) {
        while (static_cast<int>(history.size()) > snapshot) {
            auto [child, sizeOfParent] = history.back();
            history.pop_back();
            if (child == -1) continue;
            int root = parent[child];
            parent[child] = child;
            size_[root] = sizeOfParent;
        }
    }
};

class OfflineDynamicConnectivity {
    struct Operation {
        int type;
        int u, v;
    };

    using Edge = pair<int, int>;

    int n;
    vector<Operation> ops;

    static Edge normalize(int u, int v) {
        if (u > v) swap(u, v);
        return {u, v};
    }

    static long long encode(const Edge& edge) {
        return (static_cast<long long>(edge.first) << 32) ^ static_cast<unsigned int>(edge.second);
    }

    void addInterval(int node, int left, int right, int ql, int qr, const Edge& edge, vector<vector<Edge>>& seg) const {
        if (ql > right || qr < left) return;
        if (ql <= left && right <= qr) {
            seg[node].push_back(edge);
            return;
        }
        int mid = (left + right) / 2;
        addInterval(node * 2, left, mid, ql, qr, edge, seg);
        addInterval(node * 2 + 1, mid + 1, right, ql, qr, edge, seg);
    }

   public:
    explicit OfflineDynamicConnectivity(int n) : n(n) {}

    void addEdge(int u, int v) {
        auto [a, b] = normalize(u, v);
        ops.push_back({0, a, b});
    }

    void removeEdge(int u, int v) {
        auto [a, b] = normalize(u, v);
        ops.push_back({1, a, b});
    }

    void addQuery(int u, int v) {
        auto [a, b] = normalize(u, v);
        ops.push_back({2, a, b});
    }

    vector<bool> solve() const {
        int m = static_cast<int>(ops.size());
        if (m == 0) return {};

        vector<vector<Edge>> seg(4 * m);
        unordered_map<long long, pair<int, Edge>> active;
        vector<int> queryId(m, -1);
        vector<Edge> queries;

        for (int time = 0; time < m; ++time) {
            const auto& op = ops[time];
            Edge edge = {op.u, op.v};
            long long key = encode(edge);

            if (op.type == 0) {
                if (active.count(key)) {
                    throw invalid_argument("edge added twice without removal");
                }
                active[key] = {time, edge};
            } else if (op.type == 1) {
                auto it = active.find(key);
                if (it == active.end()) {
                    throw invalid_argument("removing an edge that is not active");
                }
                addInterval(1, 0, m - 1, it->second.first, time - 1, it->second.second, seg);
                active.erase(it);
            } else {
                queryId[time] = static_cast<int>(queries.size());
                queries.push_back(edge);
            }
        }

        for (const auto& [_, info] : active) {
            addInterval(1, 0, m - 1, info.first, m - 1, info.second, seg);
        }

        vector<bool> answer(queries.size(), false);
        RollbackDSU dsu(n);

        function<void(int, int, int)> dfs = [&](int node, int left, int right) {
            int snapshot = dsu.snapshot();
            for (const auto& [u, v] : seg[node]) dsu.unite(u, v);

            if (left == right) {
                if (queryId[left] != -1) {
                    const auto& [u, v] = queries[queryId[left]];
                    answer[queryId[left]] = dsu.same(u, v);
                }
            } else {
                int mid = (left + right) / 2;
                dfs(node * 2, left, mid);
                dfs(node * 2 + 1, mid + 1, right);
            }

            dsu.rollback(snapshot);
        };

        dfs(1, 0, m - 1);
        return answer;
    }
};

bool possibleBipartition(int n, vector<vector<int>>& dislikes) {
    DSU dsu(2 * n);
    for (auto& e : dislikes) {
        int u = e[0] - 1;
        int v = e[1] - 1;
        int uEnemy = u + n;
        int vEnemy = v + n;
        if (dsu.find(u) == dsu.find(v)) return false;
        dsu.unite(u, vEnemy);
        dsu.unite(v, uEnemy);
    }
    return true;
}

