vector<long long> shortestPathDAG(int V, vector<vector<pair<int, int>>>& adj, int src) {
    vector<int> vis(V, 0), order;
    for (int i = 0; i < V; i++)
        if (!vis[i]) dfs(i, adj, vis, order);
    reverse(order.begin(), order.end());
    const long long INF = 1e18;
    vector<long long> dist(V, INF);
    dist[src] = 0;
    for (int u : order) {
        if (dist[u] == INF) continue;
        for (auto [v, w] : adj[u]) dist[v] = min(dist[v], dist[u] + w);
    }
