long long prim(int V, vector<vector<pair<int, int>>>& adj) {
    const long long INF = 1e18;
    vector<long long> key(V, INF);
    vector<bool> used(V, false);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    key[0] = 0;
    pq.push({0, 0});
    long long ans = 0;
    while (!pq.empty()) {
        auto [w, u] = pq.top();
        pq.pop();
        if (used[u]) continue;
        used[u] = true;
        ans += w;
        for (auto [v, wt] : adj[u]) {
            if (!used[v] && wt < key[v]) {
                key[v] = wt;
                pq.push({wt, v});
            }
        }
    }
    return ans;
}

