class TarjanSCC {
    int timer = 0;
    vector<int> disc, low, inStack;
    stack<int> st;
    vector<vector<int>> scc;
    void dfs(int u, vector<vector<int>>& adj) {
        disc[u] = low[u] = timer++;
        st.push(u);
        inStack[u] = 1;
        for (int v : adj[u]) {
            if (disc[v] == -1) {
                dfs(v, adj);
                low[u] = min(low[u], low[v]);
            } else if (inStack[v]) {
                low[u] = min(low[u], disc[v]);
            }
        }
        if (low[u] == disc[u]) {
            vector<int> comp;
            while (true) {
                int v = st.top();
                st.pop();
                inStack[v] = 0;
                comp.push_back(v);
                if (v == u) break;
            }
            scc.push_back(comp);
        }
    }

   public:
    vector<vector<int>> getSCC(int V, vector<vector<int>>& adj) {
        disc.assign(V, -1);
        low.resize(V);
        inStack.assign(V, 0);
        for (int i = 0; i < V; i++)
            if (disc[i] == -1) dfs(i, adj);
        return scc;
    }
};

