bool hasEulerianPath(int n, const vector<vector<int>>& adj) {
    int odd = 0;
    int start = -1;
    for (int i = 0; i < n; ++i) {
        if (adj[i].size() % 2 == 1) ++odd;
        if (!adj[i].empty() && start == -1) start = i;
    }

    if (start == -1) return true;

    vector<int> vis(n, 0);
    stack<int> st;
    st.push(start);
    vis[start] = 1;
    while (!st.empty()) {
        int u = st.top();
        st.pop();
        for (int v : adj[u]) {
            if (vis[v]) continue;
            vis[v] = 1;
            st.push(v);
        }
    }

    for (int i = 0; i < n; ++i) {
        if (!adj[i].empty() && !vis[i]) return false;
    }
    return odd == 0 || odd == 2;
}

bool hamiltonianPath(int V, vector<vector<int>>& adj) {
    int N = 1 << V;
    vector<vector<char>> dp(N, vector<char>(V, false));
    for (int i = 0; i < V; i++) dp[1 << i][i] = true;
    for (int mask = 0; mask < N; mask++) {
        for (int u = 0; u < V; u++) {
            if (!dp[mask][u]) continue;
            for (int v : adj[u]) {
                if (!(mask & (1 << v))) {
                    dp[mask | (1 << v)][v] = true;
                }
            }
        }
    }
    for (int i = 0; i < V; i++)
        if (dp[N - 1][i]) return true;
    return false;
}

