struct Dinic {
    struct Edge {
        int to, rev;
        long long cap;
    };

    vector<vector<Edge>> g;
    vector<int> level, ptr;

    explicit Dinic(int n) : g(n), level(n), ptr(n) {}

    void addEdge(int u, int v, long long cap) {
        Edge a{v, static_cast<int>(g[v].size()), cap};
        Edge b{u, static_cast<int>(g[u].size()), 0};
        g[u].push_back(a);
        g[v].push_back(b);
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        q.push(s);
        level[s] = 0;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (const auto& e : g[u]) {
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    long long dfs(int u, int t, long long pushed) {
        if (u == t || pushed == 0) return pushed;
        for (int& i = ptr[u]; i < static_cast<int>(g[u].size()); ++i) {
            Edge& e = g[u][i];
            if (e.cap == 0 || level[e.to] != level[u] + 1) continue;
            long long sent = dfs(e.to, t, min(pushed, e.cap));
            if (sent == 0) continue;
            e.cap -= sent;
            g[e.to][e.rev].cap += sent;
            return sent;
        }
        return 0;
    }

    long long maxFlow(int s, int t) {
        long long flow = 0;
        while (bfs(s, t)) {
            fill(ptr.begin(), ptr.end(), 0);
            while (long long pushed = dfs(s, t, LLONG_MAX)) {
                flow += pushed;
            }
        }
        return flow;
    }

    const vector<vector<Edge>>& graph() const {
        return g;
    }
};

vector<int> solve2SAT(int n, vector<pair<int, int>>& clauses) {
    int N = 2 * n;
    vector<vector<int>> adj(N);
    auto node = [&](int x) {
        int v = abs(x) - 1;
        return x > 0 ? 2 * v : 2 * v + 1;
    };
    auto neg = [&](int x) { return x ^ 1; };
    for (auto [a, b] : clauses) {
        int A = node(a);
        int B = node(b);
        adj[neg(A)].push_back(B);
        adj[neg(B)].push_back(A);
    }
    // Kosaraju
    vector<int> vis(N), order;
    function<void(int)> dfs1 = [&](int u) {
        vis[u] = 1;
        for (int v : adj[u])
            if (!vis[v]) dfs1(v);
        order.push_back(u);
    };
    for (int i = 0; i < N; i++)
        if (!vis[i]) dfs1(i);
    vector<vector<int>> rev(N);
    for (int u = 0; u < N; u++)
        for (int v : adj[u]) rev[v].push_back(u);
    vector<int> comp(N, -1);
    function<void(int, int)> dfs2 = [&](int u, int c) {
        comp[u] = c;
        for (int v : rev[u])
            if (comp[v] == -1) dfs2(v, c);
    };
    reverse(order.begin(), order.end());
    int c = 0;
    for (int u : order)
        if (comp[u] == -1) dfs2(u, c++);
    for (int i = 0; i < n; i++) {
        if (comp[2 * i] == comp[2 * i + 1]) return {};
    }
    vector<int> assignment(n);
    for (int i = 0; i < n; i++) assignment[i] = comp[2 * i] > comp[2 * i + 1];
    return assignment;
}

