class LCA {
    int log_;
    vector<int> depth;
    vector<vector<int>> up;

    void dfs(int u, int parent, const vector<vector<int>>& adj) {
        up[u][0] = parent;
        for (int j = 1; j < log_; ++j) {
            up[u][j] = up[up[u][j - 1]][j - 1];
        }
        for (int v : adj[u]) {
            if (v == parent) continue;
            depth[v] = depth[u] + 1;
            dfs(v, u, adj);
        }
    }

   public:
    explicit LCA(const vector<vector<int>>& adj, int root = 0) {
        int n = static_cast<int>(adj.size());
        log_ = 1;
        while ((1LL << log_) <= max(1, n)) ++log_;
        depth.assign(n, 0);
        up.assign(n, vector<int>(log_, root));
        if (n > 0) dfs(root, root, adj);
    }

    int query(int a, int b) const {
        if (depth[a] < depth[b]) swap(a, b);
        int diff = depth[a] - depth[b];
        for (int j = 0; j < log_; ++j) {
            if (diff & (1 << j)) a = up[a][j];
        }
        if (a == b) return a;
        for (int j = log_ - 1; j >= 0; --j) {
            if (up[a][j] != up[b][j]) {
                a = up[a][j];
                b = up[b][j];
            }
        }
        return up[a][0];
    }
};

class RollbackDSU {
    vector<int> parent, sz;
    vector<pair<int, int>> history;

   public:
    RollbackDSU(int n) {
        parent.resize(n);
        sz.assign(n, 1);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        while (x != parent[x]) x = parent[x];
        return x;
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) {
            history.push_back({-1, -1});
            return;
        }
        if (sz[a] < sz[b]) swap(a, b);
        history.push_back({a, b});
        parent[b] = a;
        sz[a] += sz[b];
    }
    void rollback() {
        auto [a, b] = history.back();
        history.pop_back();
        if (a == -1) return;
        parent[b] = b;
        sz[a] -= sz[b];
    }
};

vector<int> shortestPath(int V, vector<vector<pair<int, int>>>& adj, int src, int dest) {
    const long long INF = 1e18;
    vector<long long> dist(V, INF);
    vector<int> parent(V, -1);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;
        for (auto [v, w] : adj[u]) {
            if (d + w < dist[v]) {
                dist[v] = d + w;
                parent[v] = u;
                pq.push({dist[v], v});
            }
        }
    }
    if (dist[dest] == INF) return {};
    vector<int> path;
    for (int u = dest; u != -1; u = parent[u]) path.push_back(u);
    reverse(path.begin(), path.end());
    return path;
}

void transitiveClosure(vector<vector<int>>& reach) {
    int V = reach.size();
    for (int k = 0; k < V; k++) {
        for (int i = 0; i < V; i++) {
            for (int j = 0; j < V; j++) {
                reach[i][j] = reach[i][j] || (reach[i][k] && reach[k][j]);
            }
        }
    }
}

