struct Edge {
    int u, v, w;
};

struct KruskalReconstructionForest {
    vector<vector<int>> tree;
    vector<int> mergeWeight;
    vector<int> roots;
};

KruskalReconstructionForest buildKruskalTree(int n, vector<Edge> edges) {
    if (n == 0) return {};

    sort(edges.begin(), edges.end(), [](const Edge& a, const Edge& b) { return a.w < b.w; });

    vector<vector<int>> tree(2 * n);
    vector<int> mergeWeight(2 * n, 0);
    vector<int> parent(2 * n);
    iota(parent.begin(), parent.end(), 0);

    function<int(int)> find = [&](int x) { return parent[x] == x ? x : parent[x] = find(parent[x]); };

    int next = n;
    for (const auto& e : edges) {
        int a = find(e.u);
        int b = find(e.v);
        if (a == b) continue;
        tree[next].push_back(a);
        tree[next].push_back(b);
        mergeWeight[next] = e.w;
        parent[a] = next;
        parent[b] = next;
        parent[next] = next;
        ++next;
    }

    vector<int> roots;
    vector<int> seen(next, 0);
    for (int i = 0; i < n; ++i) {
        int root = find(i);
        if (!seen[root]) {
            seen[root] = 1;
            roots.push_back(root);
        }
    }

    tree.resize(next);
    mergeWeight.resize(next);
    return {tree, mergeWeight, roots};
}

int minimaxPath(int V, vector<vector<pair<int, int>>>& adj, int src, int dest) {
    const int INF = 1e9;
    vector<int> dist(V, INF);
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;
        for (auto [v, w] : adj[u]) {
            int nd = max(d, w);
            if (nd < dist[v]) {
                dist[v] = nd;
                pq.push({nd, v});
            }
        }
    }
    return dist[dest];
}

