int shortestPathLength(const vector<vector<int>>& adj) {
    int n = static_cast<int>(adj.size());
    if (n <= 1) return 0;

    int fullMask = (1 << n) - 1;
    vector<vector<int>> dist(n, vector<int>(1 << n, -1));
    queue<pair<int, int>> q;

    for (int i = 0; i < n; ++i) {
        dist[i][1 << i] = 0;
        q.push({i, 1 << i});
    }

    while (!q.empty()) {
        auto [u, mask] = q.front();
        q.pop();
        if (mask == fullMask) return dist[u][mask];

        for (int v : adj[u]) {
            int nextMask = mask | (1 << v);
            if (dist[v][nextMask] != -1) continue;
            dist[v][nextMask] = dist[u][mask] + 1;
            q.push({v, nextMask});
        }
    }

    return -1;
}

int cheapest(int V, vector<Edge>& edges, int src, int dst, int K) {
    const int INF = 1e9;
    vector<int> dist(V, INF);
    dist[src] = 0;
    for (int i = 0; i <= K; i++) {
        vector<int> ndist = dist;
        for (auto e : edges) {
            if (dist[e.u] == INF) continue;
            ndist[e.v] = min(ndist[e.v], dist[e.u] + e.w);
        }
        dist = ndist;
    }
    return dist[dst] == INF ? -1 : dist[dst];
}

int unboundedKnapsack(vector<int>& wt, vector<int>& val, int W) {
    int n = wt.size();
    vector<int> dp(W + 1, 0);
    for (int w = 0; w <= W; w++) {
        for (int i = 0; i < n; i++) {
            if (wt[i] <= w) {
                dp[w] = max(dp[w], val[i] + dp[w - wt[i]]);
            }
        }
    }
    return dp[W];
}

int coinChange(vector<int>& coins, int amount) {
    const int INF = 1e9;
    vector<int> dp(amount + 1, INF);
    dp[0] = 0;
    for (int x = 1; x <= amount; x++) {
        for (int coin : coins) {
            if (coin <= x) {
                dp[x] = min(dp[x], 1 + dp[x - coin]);
            }
        }
    }
    return dp[amount] == INF ? -1 : dp[amount];
}

long long coinChangeWays(vector<int>& coins, int amount) {
    vector<long long> dp(amount + 1, 0);
    dp[0] = 1;
    for (int coin : coins) {
        for (int x = coin; x <= amount; x++) {
            dp[x] += dp[x - coin];
        }
    }
    return dp[amount];
}

bool canPartition(vector<int>& nums) {
    int sum = accumulate(nums.begin(), nums.end(), 0);
    if (sum % 2) return false;
    int target = sum / 2;
    vector<bool> dp(target + 1, false);
    dp[0] = true;
    for (int x : nums) {
        for (int s = target; s >= x; s--) {
            dp[s] = dp[s] || dp[s - x];
        }
    }
    return dp[target];
}

int findTargetSumWays(vector<int>& nums, int target) {
    int sum = accumulate(nums.begin(), nums.end(), 0);
    if (abs(target) > sum || (sum + target) % 2) return 0;
    int need = (sum + target) / 2;
    vector<int> dp(need + 1, 0);
    dp[0] = 1;
    for (int x : nums) {
        for (int s = need; s >= x; s--) {
            dp[s] += dp[s - x];
        }
    }
    return dp[need];
}

int rob(vector<int>& nums) {
    int prev2 = 0;
    int prev1 = 0;
    for (int x : nums) {
        int curr = max(prev1, prev2 + x);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

int solve(vector<int>& nums, int l, int r) {
    int prev2 = 0, prev1 = 0;
    for (int i = l; i <= r; i++) {
        int curr = max(prev1, prev2 + nums[i]);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}
int robCircular(vector<int>& nums) {
    int n = nums.size();
    if (n == 1) return nums[0];
    return max(solve(nums, 0, n - 2), solve(nums, 1, n - 1));
}

int maxProfit(int K, const vector<int>& prices) {
    int n = static_cast<int>(prices.size());
    if (n == 0 || K == 0) return 0;
    if (K >= n / 2) {
        int profit = 0;
        for (int i = 1; i < n; ++i) {
            profit += max(0, prices[i] - prices[i - 1]);
        }
        return profit;
    }

    const int NEG_INF = numeric_limits<int>::min() / 4;
    vector<int> hold(K + 1, NEG_INF), cash(K + 1, 0);
    for (int price : prices) {
        vector<int> nextHold = hold;
        vector<int> nextCash = cash;
        for (int k = 1; k <= K; ++k) {
            nextHold[k] = max(hold[k], cash[k - 1] - price);
            nextCash[k] = max(cash[k], hold[k] + price);
        }
        hold.swap(nextHold);
        cash.swap(nextCash);
    }
    return cash[K];
}

int maxProfit(const vector<int>& prices) {
    if (prices.empty()) return 0;
    const int NEG_INF = numeric_limits<int>::min() / 4;
    int hold = -prices[0];
    int sold = NEG_INF;
    int rest = 0;
    for (int i = 1; i < static_cast<int>(prices.size()); ++i) {
        int nextHold = max(hold, rest - prices[i]);
        int nextSold = hold + prices[i];
        int nextRest = max(rest, sold);
        hold = nextHold;
        sold = nextSold;
        rest = nextRest;
    }
    return max(rest, sold);
}

int maxProfit(const vector<int>& prices, int fee) {
    if (prices.empty()) return 0;
    int hold = -prices[0];
    int cash = 0;
    for (int i = 1; i < static_cast<int>(prices.size()); ++i) {
        int nextHold = max(hold, cash - prices[i]);
        int nextCash = max(cash, hold + prices[i] - fee);
        hold = nextHold;
        cash = nextCash;
    }
    return cash;
}

int maxCoins(vector<int>& nums) {
    int n = nums.size();
    nums.insert(nums.begin(), 1);
    nums.push_back(1);
    vector<vector<int>> dp(n + 2, vector<int>(n + 2, 0));
    for (int len = 1; len <= n; len++) {
        for (int l = 1; l + len - 1 <= n; l++) {
            int r = l + len - 1;
            for (int k = l; k <= r; k++) {
                dp[l][r] = max(dp[l][r], nums[l - 1] * nums[k] * nums[r + 1] + dp[l][k - 1] + dp[k + 1][r]);
            }
        }
    }
    return dp[1][n];
}

long long solve(string& s, int l, int r, bool want, vector<vector<vector<long long>>>& dp) {
    if (l == r) return (s[l] == 'T') == want;
    if (dp[l][r][want] != -1) return dp[l][r][want];
    long long ans = 0;
    for (int k = l + 1; k < r; k += 2) {
        long long LT = solve(s, l, k - 1, true, dp);
        long long LF = solve(s, l, k - 1, false, dp);
        long long RT = solve(s, k + 1, r, true, dp);
        long long RF = solve(s, k + 1, r, false, dp);
        if (s[k] == '&') {
            if (want)
                ans += LT * RT;
            else
                ans += LT * RF + LF * RT + LF * RF;
        } else if (s[k] == '|') {
            if (want)
                ans += LT * RT + LT * RF + LF * RT;
            else
                ans += LF * RF;
        } else {
            if (want)
                ans += LT * RF + LF * RT;
            else
                ans += LT * RT + LF * RF;
        }
    }
    return dp[l][r][want] = ans;
}

void dfs(int u, vector<vector<pair<int, int>>>& adj, vector<int>& vis, stack<int>& st) {
    vis[u] = 1;
    for (auto [v, w] : adj[u]) {
        if (!vis[v]) dfs(v, adj, vis, st);
    }
    st.push(u);
}
vector<int> shortestPathDAG(int n, vector<vector<pair<int, int>>>& adj, int src) {
    vector<int> vis(n, 0);
    stack<int> st;
    for (int i = 0; i < n; i++)
        if (!vis[i]) dfs(i, adj, vis, st);
    vector<int> dist(n, 1e9);
    dist[src] = 0;
    while (!st.empty()) {
        int u = st.top();
        st.pop();
        if (dist[u] == 1e9) continue;
        for (auto [v, w] : adj[u]) {
            dist[v] = min(dist[v], dist[u] + w);
        }
    }
    return dist;
}

pair<int, int> solve(TreeNode* root) {
    if (!root) return {0, 0};
    auto left = solve(root->left);
    auto right = solve(root->right);
    // Include current node
    int take = 1 + left.second + right.second;
    // Exclude current node
    int skip = max(left.first, left.second) + max(right.first, right.second);
    return {take, skip};
}

int dfs(TreeNode* root, int& ans) {
    if (!root) return 0;
    int left = max(0, dfs(root->left, ans));
    int right = max(0, dfs(root->right, ans));
    ans = max(ans, root->val + left + right);
    return root->val + max(left, right);
}

long long dp[20][11][2][2];
bool vis[20][11][2][2];
long long solve(string& s, int pos, int prev, int tight, int started) {
    if (pos == s.size()) return 1;
    if (vis[pos][prev + 1][tight][started]) return dp[pos][prev + 1][tight][started];
    vis[pos][prev + 1][tight][started] = true;
    int limit = tight ? s[pos] - '0' : 9;
    long long ans = 0;
    for (int d = 0; d <= limit; d++) {
        int newTight = tight && (d == limit);
        if (started && d == prev) continue;
        if (!started && d == 0) {
            ans += solve(s, pos + 1, -1, newTight, 0);
        } else {
            ans += solve(s, pos + 1, d, newTight, 1);
        }
    }
    return dp[pos][prev + 1][tight][started] = ans;
}

int solve(int worker, int mask, vector<vector<int>>& cost, vector<int>& dp) {
    int n = cost.size();
    if (worker == n) return 0;
    if (dp[mask] != -1) return dp[mask];
    int ans = 1e9;
    for (int job = 0; job < n; job++) {
        if (!(mask & (1 << job))) {
            ans = min(ans, cost[worker][job] + solve(worker + 1, mask | (1 << job), cost, dp));
        }
    }
    return dp[mask] = ans;
}

void SOSDP(vector<int>& a) {
    int n = 0;
    while ((1 << n) < a.size()) n++;
    for (int bit = 0; bit < n; bit++) {
        for (int mask = 0; mask < (1 << n); mask++) {
            if (mask & (1 << bit)) {
                a[mask] += a[mask ^ (1 << bit)];
            }
        }
    }
}

void generateNextMasks(int row, int n, int mask, int nextMask, vector<int>& nextMasks) {
    if (row == n) {
        nextMasks.push_back(nextMask);
        return;
    }
    if (mask & (1 << row)) {
        generateNextMasks(row + 1, n, mask, nextMask, nextMasks);
        return;
    }
    generateNextMasks(row + 1, n, mask, nextMask | (1 << row), nextMasks);
    if (row + 1 < n && !(mask & (1 << (row + 1)))) {
        generateNextMasks(row + 2, n, mask, nextMask, nextMasks);
    }
}

long long countTilings(int n, int m) {
    if (n < 0 || m < 0) return 0;
    if (n > m) swap(n, m);
    vector<long long> dp(1 << n, 0), next(1 << n, 0);
    dp[0] = 1;
    for (int col = 0; col < m; ++col) {
        fill(next.begin(), next.end(), 0);
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (dp[mask] == 0) continue;
            vector<int> nextMasks;
            generateNextMasks(0, n, mask, 0, nextMasks);
            for (int newMask : nextMasks) {
                next[newMask] += dp[mask];
            }
        }
        dp.swap(next);
    }
    return dp[0];
}

void dfs1(int u, int p, vector<vector<int>>& adj, vector<int>& sub, vector<long long>& dp) {
    sub[u] = 1;
    for (int v : adj[u]) {
        if (v == p) continue;
        dfs1(v, u, adj, sub, dp);
        sub[u] += sub[v];
        dp[u] += dp[v] + sub[v];
    }
}
void dfs2(int u, int p, vector<vector<int>>& adj, vector<int>& sub, vector<long long>& dp, int n) {
    for (int v : adj[u]) {
        if (v == p) continue;
        dp[v] = dp[u] + n - 2 * sub[v];
        dfs2(v, u, adj, sub, dp, n);
    }
}

pair<int, int> dfs(int u, int p, vector<vector<int>>& adj) {
    int take = 1;
    int skip = 0;
    for (int v : adj[u]) {
        if (v == p) continue;
        auto [childTake, childSkip] = dfs(v, u, adj);
        take += min(childTake, childSkip);
        skip += childTake;
    }
    return {take, skip};
}

int maxSum(vector<int>& a) {
    int take = 0;
    int skip = 0;
    for (int x : a) {
        int newTake = skip + x;
        int newSkip = max(take, skip);
        take = newTake;
        skip = newSkip;
    }
    return max(take, skip);
}

int numDecodings(const string& s) {
    int n = static_cast<int>(s.size());
    if (n == 0 || s[0] == '0') return 0;
    int prev2 = 1;
    int prev1 = 1;
    for (int i = 1; i < n; ++i) {
        int curr = 0;
        if (s[i] != '0') curr += prev1;
        int two = (s[i - 1] - '0') * 10 + (s[i] - '0');
        if (10 <= two && two <= 26) curr += prev2;
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

bool wordBreak(string s, unordered_set<string>& dict) {
    int n = s.size();
    vector<bool> dp(n + 1, false);
    dp[0] = true;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < i; j++) {
            if (dp[j] && dict.count(s.substr(j, i - j))) {
                dp[i] = true;
                break;
            }
        }
    }
    return dp[n];
}

string shortestCommonSupersequence(string a, string b) {
    int n = a.size();
    int m = b.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1));
    for (int i = 0; i <= n; i++) dp[i][0] = i;
    for (int j = 0; j <= m; j++) dp[0][j] = j;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (a[i - 1] == b[j - 1])
                dp[i][j] = 1 + dp[i - 1][j - 1];
            else
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1]);
        }
    }
    string ans;
    int i = n, j = m;
    while (i > 0 && j > 0) {
        if (a[i - 1] == b[j - 1]) {
            ans += a[i - 1];
            i--;
            j--;
        } else if (dp[i - 1][j] < dp[i][j - 1]) {
            ans += a[i - 1];
            i--;
        } else {
            ans += b[j - 1];
            j--;
        }
    }
    while (i > 0) ans += a[--i];
    while (j > 0) ans += b[--j];
    reverse(ans.begin(), ans.end());
    return ans;
}

int minCost(int n, vector<int>& cuts) {
    cuts.push_back(0);
    cuts.push_back(n);
    sort(cuts.begin(), cuts.end());
    int m = cuts.size();
    vector<vector<int>> dp(m, vector<int>(m, 0));
    for (int len = 2; len < m; len++) {
        for (int l = 0; l + len < m; l++) {
            int r = l + len;
            dp[l][r] = 1e9;
            for (int k = l + 1; k < r; k++) {
                dp[l][r] = min(dp[l][r], cuts[r] - cuts[l] + dp[l][k] + dp[k][r]);
            }
        }
    }
    return dp[0][m - 1];
}

long long eggDrop(int eggs, long long floors) {
    if (floors < 0) throw invalid_argument("floors must be non-negative");
    if (floors == 0) return 0;
    if (eggs <= 0) throw invalid_argument("at least one egg is required");

    vector<long long> covered(eggs + 1, 0);
    long long moves = 0;
    while (covered[eggs] < floors) {
        ++moves;
        for (int e = eggs; e >= 1; --e) {
            if (covered[e] >= floors - covered[e - 1] - 1) {
                covered[e] = floors;
            } else {
                covered[e] += covered[e - 1] + 1;
            }
        }
    }
    return moves;
}

class Solution {
   public:
    vector<vector<string>> ans;
    vector<string> board;
    vector<int> col, diag1, diag2;
    void solve(int row, int n) {
        if (row == n) {
            ans.push_back(board);
            return;
        }
        for (int c = 0; c < n; c++) {
            if (col[c] || diag1[row - c + n - 1] || diag2[row + c]) continue;
            board[row][c] = 'Q';
            col[c] = diag1[row - c + n - 1] = diag2[row + c] = 1;
            solve(row + 1, n);
            board[row][c] = '.';
            col[c] = diag1[row - c + n - 1] = diag2[row + c] = 0;
        }
    }
    vector<vector<string>> solveNQueens(int n) {
        board = vector<string>(n, string(n, '.'));
        col.resize(n);
        diag1.resize(2 * n - 1);
        diag2.resize(2 * n - 1);
        solve(0, n);
        return ans;
    }
};

class Solution {
   public:
    bool solve(vector<vector<char>>& board, vector<int>& row, vector<int>& col, vector<int>& box) {
        int r = -1, c = -1;
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] == '.') {
                    r = i;
                    c = j;
                    break;
                }
            }
            if (r != -1) break;
        }
        if (r == -1) return true;
        int b = (r / 3) * 3 + c / 3;
        for (int num = 1; num <= 9; num++) {
            int bit = 1 << num;
            if ((row[r] & bit) || (col[c] & bit) || (box[b] & bit)) continue;
            board[r][c] = char('0' + num);
            row[r] |= bit;
            col[c] |= bit;
            box[b] |= bit;
            if (solve(board, row, col, box)) return true;
            board[r][c] = '.';
            row[r] ^= bit;
            col[c] ^= bit;
            box[b] ^= bit;
        }
        return false;
    }
    void solveSudoku(vector<vector<char>>& board) {
        vector<int> row(9), col(9), box(9);
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] == '.') continue;
                int bit = 1 << (board[i][j] - '0');
                row[i] |= bit;
                col[j] |= bit;
                box[(i / 3) * 3 + j / 3] |= bit;
            }
        }
        solve(board, row, col, box);
    }
};

class Solution {
    struct Node {
        array<int, 26> child;
        string word;

        Node() {
            child.fill(-1);
        }
    };

    vector<Node> trie;
    vector<string> ans;
    int rows = 0, cols = 0;

    void insert(const string& word) {
        int node = 0;
        for (char ch : word) {
            int c = ch - 'a';
            if (trie[node].child[c] == -1) {
                trie[node].child[c] = static_cast<int>(trie.size());
                trie.push_back(Node());
            }
            node = trie[node].child[c];
        }
        trie[node].word = word;
    }

    void dfs(vector<vector<char>>& board, int r, int c, int node) {
        if (r < 0 || r >= rows || c < 0 || c >= cols || board[r][c] == '#') return;
        char ch = board[r][c];
        int next = trie[node].child[ch - 'a'];
        if (next == -1) return;

        if (!trie[next].word.empty()) {
            ans.push_back(trie[next].word);
            trie[next].word.clear();
        }

        board[r][c] = '#';
        dfs(board, r + 1, c, next);
        dfs(board, r - 1, c, next);
        dfs(board, r, c + 1, next);
        dfs(board, r, c - 1, next);
        board[r][c] = ch;
    }

   public:
    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {
        ans.clear();
        trie.assign(1, Node());
        rows = static_cast<int>(board.size());
        if (rows == 0) return ans;
        cols = static_cast<int>(board[0].size());
        if (cols == 0) return ans;

        for (const string& word : words) {
            if (!word.empty()) insert(word);
        }
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                dfs(board, r, c, 0);
            }
        }
        return ans;
    }
};

class Solution {
   public:
    vector<vector<string>> ans;
    vector<string> cur;
    vector<vector<bool>> pal;
    void backtrack(string& s, int start) {
        if (start == s.size()) {
            ans.push_back(cur);
            return;
        }
        for (int end = start; end < s.size(); end++) {
            if (!pal[start][end]) continue;
            cur.push_back(s.substr(start, end - start + 1));
            backtrack(s, end + 1);
            cur.pop_back();
        }
    }
    vector<vector<string>> partition(string s) {
        int n = s.size();
        pal.assign(n, vector<bool>(n, false));
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                if (s[i] == s[j] && (j - i <= 2 || pal[i + 1][j - 1])) pal[i][j] = true;
            }
        }
        backtrack(s, 0);
        return ans;
    }
};

class Solution {
   public:
    vector<vector<int>> ans;
    vector<int> cur;
    void solve(vector<int>& nums, int start, int target) {
        if (target == 0) {
            ans.push_back(cur);
            return;
        }
        for (int i = start; i < nums.size(); i++) {
            if (i > start && nums[i] == nums[i - 1]) continue;
            if (nums[i] > target) break;
            cur.push_back(nums[i]);
            solve(nums, i + 1, target - nums[i]);
            cur.pop_back();
        }
    }
    vector<vector<int>> combinationSum2(vector<int>& nums, int target) {
        sort(nums.begin(), nums.end());
        solve(nums, 0, target);
        return ans;
    }
};

class Solution {
   public:
    vector<vector<int>> ans;
    vector<int> cur;
    vector<bool> used;
    void solve(vector<int>& nums) {
        if (cur.size() == nums.size()) {
            ans.push_back(cur);
            return;
        }
        for (int i = 0; i < nums.size(); i++) {
            if (used[i]) continue;
            if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;
            used[i] = true;
            cur.push_back(nums[i]);
            solve(nums);
            cur.pop_back();
            used[i] = false;
        }
    }
    vector<vector<int>> permuteUnique(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        used.resize(nums.size());
        solve(nums);
        return ans;
    }
};

class Solution {
   public:
    vector<string> ans;
    void solve(string& cur, int open, int close, int n) {
        if (cur.size() == 2 * n) {
            ans.push_back(cur);
            return;
        }
        if (open < n) {
            cur.push_back('(');
            solve(cur, open + 1, close, n);
            cur.pop_back();
        }
        if (close < open) {
            cur.push_back(')');
            solve(cur, open, close + 1, n);
            cur.pop_back();
        }
    }
    vector<string> generateParenthesis(int n) {
        string cur;
        solve(cur, 0, 0, n);
        return ans;
    }
};

class Solution {
   public:
    unordered_set<string> dict;
    unordered_map<int, vector<string>> memo;
    vector<string> solve(string& s, int start) {
        if (start == s.size()) return {""};
        if (memo.count(start)) return memo[start];
        vector<string> ans;
        string word;
        for (int i = start; i < s.size(); i++) {
            word += s[i];
            if (!dict.count(word)) continue;
            vector<string> suffix = solve(s, i + 1);
            for (string& x : suffix) {
                if (x.empty())
                    ans.push_back(word);
                else
                    ans.push_back(word + " " + x);
            }
        }
        return memo[start] = ans;
    }
    vector<string> wordBreak(string s, vector<string>& wordDict) {
        for (auto& word : wordDict) dict.insert(word);
        return solve(s, 0);
    }
};

class Solution {
    vector<int> digit;
    vector<int> used;
    vector<int> leading;

    bool solve(vector<string>& words, const string& result, int col, int row, int carry) {
        if (col == static_cast<int>(result.size())) return carry == 0;

        if (row == static_cast<int>(words.size())) {
            int resultPos = static_cast<int>(result.size()) - 1 - col;
            int ch = result[resultPos] - 'A';
            int need = carry % 10;
            int nextCarry = carry / 10;

            if (digit[ch] != -1) {
                return digit[ch] == need && solve(words, result, col + 1, 0, nextCarry);
            }
            if (used[need] || (need == 0 && leading[ch])) return false;

            digit[ch] = need;
            used[need] = 1;
            if (solve(words, result, col + 1, 0, nextCarry)) return true;
            digit[ch] = -1;
            used[need] = 0;
            return false;
        }

        if (col >= static_cast<int>(words[row].size())) {
            return solve(words, result, col, row + 1, carry);
        }

        int pos = static_cast<int>(words[row].size()) - 1 - col;
        int ch = words[row][pos] - 'A';
        if (digit[ch] != -1) {
            return solve(words, result, col, row + 1, carry + digit[ch]);
        }

        for (int d = 0; d <= 9; ++d) {
            if (used[d] || (d == 0 && leading[ch])) continue;
            digit[ch] = d;
            used[d] = 1;
            if (solve(words, result, col, row + 1, carry + d)) return true;
            digit[ch] = -1;
            used[d] = 0;
        }
        return false;
    }

   public:
    bool isSolvable(vector<string>& words, string result) {
        unordered_set<char> distinct;
        int maxLen = 0;
        for (const string& word : words) {
            maxLen = max(maxLen, static_cast<int>(word.size()));
            if (word.size() > 1) distinct.insert(word.front());
            for (char ch : word) distinct.insert(ch);
        }
        if (result.size() > 1) distinct.insert(result.front());
        for (char ch : result) distinct.insert(ch);
        if (distinct.size() > 10 || result.size() < static_cast<size_t>(maxLen) ||
            result.size() > static_cast<size_t>(maxLen + 1)) {
            return false;
        }

        digit.assign(26, -1);
        used.assign(10, 0);
        leading.assign(26, 0);
        for (const string& word : words) {
            if (word.size() > 1) leading[word.front() - 'A'] = 1;
        }
        if (result.size() > 1) leading[result.front() - 'A'] = 1;

        return solve(words, result, 0, 0, 0);
    }
};

vector<int> zeroOneBFS(int n, vector<vector<pair<int, int>>>& adj, int src) {
    const int INF = 1e9;
    vector<int> dist(n, INF);
    deque<int> dq;
    dist[src] = 0;
    dq.push_front(src);
    while (!dq.empty()) {
        int u = dq.front();
        dq.pop_front();
        for (auto [v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                if (w == 0)
                    dq.push_front(v);
                else
                    dq.push_back(v);
            }
        }
    }
    return dist;
}

vector<int> shortestPath(int n, vector<vector<pair<int, int>>>& adj, int src, int dest) {
    const long long INF = 1e18;
    vector<long long> dist(n, INF);
    vector<int> parent(n, -1);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;
        for (auto [v, w] : adj[u]) {
            if (d + w < dist[v]) {
                dist[v] = d + w;
                parent[v] = u;
                pq.push({dist[v], v});
            }
        }
    }
    if (dist[dest] == INF) return {};
    vector<int> path;
    for (int v = dest; v != -1; v = parent[v]) path.push_back(v);
    reverse(path.begin(), path.end());
    return path;
}

long long shortestKEdges(int n, vector<vector<pair<int, int>>>& adj, int src, int dest, int K) {
    const long long INF = 1e18;
    vector<long long> prev(n, INF);
    prev[src] = 0;
    for (int edges = 1; edges <= K; edges++) {
        vector<long long> curr(n, INF);
        for (int u = 0; u < n; u++) {
            if (prev[u] == INF) continue;
            for (auto [v, w] : adj[u]) {
                curr[v] = min(curr[v], prev[u] + w);
            }
        }
        prev = curr;
    }
    return prev[dest];
}

vector<long long> countShortestPaths(int n, vector<vector<pair<int, int>>>& adj, int src) {
    const long long INF = 1e18;
    const long long MOD = 1e9 + 7;
    vector<long long> dist(n, INF);
    vector<long long> ways(n, 0);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    dist[src] = 0;
    ways[src] = 1;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;
        for (auto [v, w] : adj[u]) {
            if (d + w < dist[v]) {
                dist[v] = d + w;
                ways[v] = ways[u];
                pq.push({dist[v], v});
            } else if (d + w == dist[v]) {
                ways[v] = (ways[v] + ways[u]) % MOD;
            }
        }
    }
    return ways;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> eulerianPath(int n, const vector<pair<int, int>>& edges) {
    if (n == 0) return {};
    if (edges.empty()) return {0};

    vector<vector<int>> adj(n), undirected(n);
    vector<int> indegree(n, 0), outdegree(n, 0), ptr(n, 0);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        undirected[u].push_back(v);
        undirected[v].push_back(u);
        ++outdegree[u];
        ++indegree[v];
    }

    int start = -1, end = -1;
    for (int i = 0; i < n; ++i) {
        int diff = outdegree[i] - indegree[i];
        if (abs(diff) > 1) return {};
        if (diff == 1) {
            if (start != -1) return {};
            start = i;
        } else if (diff == -1) {
            if (end != -1) return {};
            end = i;
        }
    }
    if ((start == -1) != (end == -1)) return {};

    if (start == -1) {
        for (int i = 0; i < n; ++i) {
            if (outdegree[i] > 0) {
                start = i;
                break;
            }
        }
    }

    vector<int> vis(n, 0);
    stack<int> st;
    st.push(start);
    vis[start] = 1;
    while (!st.empty()) {
        int u = st.top();
        st.pop();
        for (int v : undirected[u]) {
            if (vis[v]) continue;
            vis[v] = 1;
            st.push(v);
        }
    }
    for (int i = 0; i < n; ++i) {
        if ((indegree[i] + outdegree[i] > 0) && !vis[i]) return {};
    }

    vector<int> path;
    function<void(int)> dfs = [&](int u) {
        while (ptr[u] < static_cast<int>(adj[u].size())) {
            dfs(adj[u][ptr[u]++]);
        }
        path.push_back(u);
    };

    dfs(start);
    if (static_cast<int>(path.size()) != static_cast<int>(edges.size()) + 1) return {};
    reverse(path.begin(), path.end());
    return path;
}

#include <bits/stdc++.h>
using namespace std;

bool hasEulerianCircuit(int n, const vector<pair<int, int>>& edges) {
    vector<vector<int>> undirected(n);
    vector<int> indegree(n, 0), outdegree(n, 0);
    for (const auto& [u, v] : edges) {
        ++outdegree[u];
        ++indegree[v];
        undirected[u].push_back(v);
        undirected[v].push_back(u);
    }

    int start = -1;
    for (int i = 0; i < n; ++i) {
        if (indegree[i] != outdegree[i]) return false;
        if (indegree[i] + outdegree[i] > 0 && start == -1) start = i;
    }
    if (start == -1) return true;

    vector<int> vis(n, 0);
    stack<int> st;
    st.push(start);
    vis[start] = 1;
    while (!st.empty()) {
        int u = st.top();
        st.pop();
        for (int v : undirected[u]) {
            if (vis[v]) continue;
            vis[v] = 1;
            st.push(v);
        }
    }

    for (int i = 0; i < n; ++i) {
        if (indegree[i] + outdegree[i] > 0 && !vis[i]) return false;
    }
    return true;
}

bool hamiltonianPath(int n, vector<vector<int>>& adj) {
    int N = 1 << n;
    vector<vector<bool>> dp(N, vector<bool>(n, false));
    for (int i = 0; i < n; i++) dp[1 << i][i] = true;
    for (int mask = 0; mask < N; mask++) {
        for (int u = 0; u < n; u++) {
            if (!dp[mask][u]) continue;
            for (int v : adj[u]) {
                if (!(mask & (1 << v))) {
                    dp[mask | (1 << v)][v] = true;
                }
            }
        }
    }
    for (int i = 0; i < n; i++) {
        if (dp[N - 1][i]) return true;
    }
    return false;
}

