class TwoSAT {
    int n;
    vector<vector<int>> g, rg;
    vector<int> order, comp, assignment;

    int node(int var, bool isTrue) const {
        return 2 * var + (isTrue ? 0 : 1);
    }

    int neg(int x) const {
        return x ^ 1;
    }

    void addImplication(int u, int v) {
        g[u].push_back(v);
        rg[v].push_back(u);
    }

   public:
    explicit TwoSAT(int n) : n(n), g(2 * n), rg(2 * n), assignment(n, 0) {}

    void addClause(int x, bool xVal, int y, bool yVal) {
        int a = node(x, xVal);
        int b = node(y, yVal);
        addImplication(neg(a), b);
        addImplication(neg(b), a);
    }

    bool satisfiable() {
        int N = 2 * n;
        order.clear();
        comp.assign(N, -1);

        vector<int> vis(N, 0);
        function<void(int)> dfs1 = [&](int u) {
            vis[u] = 1;
            for (int v : g[u]) {
                if (!vis[v]) dfs1(v);
            }
            order.push_back(u);
        };

        for (int i = 0; i < N; ++i) {
            if (!vis[i]) dfs1(i);
        }

        reverse(order.begin(), order.end());
        function<void(int, int)> dfs2 = [&](int u, int color) {
            comp[u] = color;
            for (int v : rg[u]) {
                if (comp[v] == -1) dfs2(v, color);
            }
        };

        int colors = 0;
        for (int u : order) {
            if (comp[u] == -1) dfs2(u, colors++);
        }

        for (int i = 0; i < n; ++i) {
            if (comp[2 * i] == comp[2 * i + 1]) return false;
            assignment[i] = comp[2 * i] > comp[2 * i + 1];
        }
        return true;
    }

    const vector<int>& values() const {
        return assignment;
    }
};

int minEdgesToMakeStrong(int components, vector<int>& indegree, vector<int>& outdegree) {
    if (components == 1) return 0;
    int sources = 0;
    int sinks = 0;
    for (int i = 0; i < components; i++) {
        if (indegree[i] == 0) sources++;
        if (outdegree[i] == 0) sinks++;
    }
    return max(sources, sinks);
}

