long long shortestWithDiscount(int n, const vector<vector<pair<int, int>>>& adj, int src, int dest) {
    const long long INF = LLONG_MAX / 4;
    vector<vector<long long>> dist(n, vector<long long>(2, INF));
    using State = tuple<long long, int, int>;
    priority_queue<State, vector<State>, greater<State>> pq;

    dist[src][0] = 0;
    pq.push({0, src, 0});

    while (!pq.empty()) {
        auto [d, u, used] = pq.top();
        pq.pop();
        if (d != dist[u][used]) continue;

        for (auto [v, w] : adj[u]) {
            if (d + w < dist[v][used]) {
                dist[v][used] = d + w;
                pq.push({dist[v][used], v, used});
            }
            if (used == 0 && d < dist[v][1]) {
                dist[v][1] = d;
                pq.push({d, v, 1});
            }
        }
    }

    long long ans = min(dist[dest][0], dist[dest][1]);
    return ans == INF ? -1 : ans;
}

vector<int> multiSourceBFS(int n, vector<vector<int>>& adj, vector<int>& sources) {
    vector<int> dist(n, -1);
    queue<int> q;
    for (int src : sources) {
        dist[src] = 0;
        q.push(src);
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (dist[v] != -1) continue;
            dist[v] = dist[u] + 1;
            q.push(v);
        }
    }
    return dist;
}

int shortestPath(vector<vector<int>>& grid, int K) {
    int n = grid.size();
    int m = grid[0].size();
    vector<vector<int>> best(n, vector<int>(m, K + 1));
    queue<tuple<int, int, int>> q;
    q.push({0, 0, 0});
    best[0][0] = 0;
    int dist = 0;
    int dr[] = {1, -1, 0, 0};
    int dc[] = {0, 0, 1, -1};
    while (!q.empty()) {
        int sz = q.size();
        while (sz--) {
            auto [r, c, used] = q.front();
            q.pop();
            if (r == n - 1 && c == m - 1) return dist;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                int nu = used + grid[nr][nc];
                if (nu <= K && nu < best[nr][nc]) {
                    best[nr][nc] = nu;
                    q.push({nr, nc, nu});
                }
            }
        }
        dist++;
    }
    return -1;
}

struct Node {
    int child[26];
    int fail;
    vector<int> output;
    Node() {
        memset(child, -1, sizeof(child));
        fail = 0;
    }
};
vector<Node> trie(1);
void insert(string s, int id) {
    int node = 0;
    for (char c : s) {
        int x = c - 'a';
        if (trie[node].child[x] == -1) {
            trie[node].child[x] = trie.size();
            trie.push_back(Node());
        }
        node = trie[node].child[x];
    }
    trie[node].output.push_back(id);
}
void build() {
    queue<int> q;
    for (int c = 0; c < 26; c++) {
        int v = trie[0].child[c];
        if (v != -1) {
            trie[v].fail = 0;
            q.push(v);
        } else {
            trie[0].child[c] = 0;
        }
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int c = 0; c < 26; c++) {
            int v = trie[u].child[c];
            if (v != -1) {
                trie[v].fail = trie[trie[u].fail].child[c];
                for (int id : trie[trie[v].fail].output) trie[v].output.push_back(id);
                q.push(v);
            } else {
                trie[u].child[c] = trie[trie[u].fail].child[c];
            }
        }
    }
}
vector<pair<int, int>> search(string text) {
    vector<pair<int, int>> ans;
    int node = 0;
    for (int i = 0; i < text.size(); i++) {
        node = trie[node].child[text[i] - 'a'];
        for (int id : trie[node].output) {
            ans.push_back({id, i});
        }
    }
    return ans;
}

vector<int> buildSuffixArray(const string& s) {
    int n = static_cast<int>(s.size());
    if (n == 0) return {};
    vector<int> sa(n), rank(n), nextRank(n);
    iota(sa.begin(), sa.end(), 0);
    for (int i = 0; i < n; ++i) {
        rank[i] = static_cast<unsigned char>(s[i]);
    }
    for (int k = 1;; k <<= 1) {
        auto cmp = [&](int a, int b) {
            if (rank[a] != rank[b]) return rank[a] < rank[b];
            int ra = (a + k < n) ? rank[a + k] : -1;
            int rb = (b + k < n) ? rank[b + k] : -1;
            return ra < rb;
        };
        sort(sa.begin(), sa.end(), cmp);
        nextRank[sa[0]] = 0;
        for (int i = 1; i < n; ++i) {
            nextRank[sa[i]] = nextRank[sa[i - 1]] + (cmp(sa[i - 1], sa[i]) ? 1 : 0);
        }
        rank.swap(nextRank);
        if (rank[sa.back()] == n - 1) break;
    }
    return sa;
}

vector<int> buildLCP(const string& s, const vector<int>& sa) {
    int n = static_cast<int>(s.size());
    if (n <= 1) return {};
    vector<int> rank(n), lcp(n - 1);
    for (int i = 0; i < n; ++i) {
        rank[sa[i]] = i;
    }
    int k = 0;
    for (int i = 0; i < n; ++i) {
        int pos = rank[i];
        if (pos == n - 1) {
            k = 0;
            continue;
        }
        int j = sa[pos + 1];
        while (i + k < n && j + k < n && s[i + k] == s[j + k]) {
            ++k;
        }
        lcp[pos] = k;
        if (k) --k;
    }
    return lcp;
}

