string longestRepeatedSubstring(const string& s) {
    if (s.empty()) return "";
    vector<int> sa = buildSuffixArray(s);
    vector<int> lcp = buildLCP(s, sa);
    int bestLen = 0;
    int bestPos = 0;
    for (int i = 0; i < static_cast<int>(lcp.size()); ++i) {
        if (lcp[i] > bestLen) {
            bestLen = lcp[i];
            bestPos = sa[i];
        }
    }
    return s.substr(bestPos, bestLen);
}

