struct SuffixAutomaton {
    struct State {
        array<int, 26> next;
        int link = -1;
        int len = 0;
        long long occ = 0;

        State() {
            next.fill(-1);
        }
    };

    vector<State> st;
    int last = 0;

    SuffixAutomaton() : st(1) {}

    void reset() {
        st.assign(1, State());
        last = 0;
    }

    void extend(char ch) {
        int c = ch - 'a';
        int cur = static_cast<int>(st.size());
        st.push_back(State());
        st[cur].len = st[last].len + 1;
        st[cur].occ = 1;

        int p = last;
        while (p != -1 && st[p].next[c] == -1) {
            st[p].next[c] = cur;
            p = st[p].link;
        }
        if (p == -1) {
            st[cur].link = 0;
        } else {
            int q = st[p].next[c];
            if (st[p].len + 1 == st[q].len) {
                st[cur].link = q;
            } else {
                int clone = static_cast<int>(st.size());
                st.push_back(st[q]);
                st[clone].len = st[p].len + 1;
                st[clone].occ = 0;
                while (p != -1 && st[p].next[c] == q) {
                    st[p].next[c] = clone;
                    p = st[p].link;
                }
                st[q].link = st[cur].link = clone;
            }
        }
        last = cur;
    }

    void build(const string& s) {
        reset();
        for (char ch : s) extend(ch);
    }

    bool contains(const string& pattern) const {
        int v = 0;
        for (char ch : pattern) {
            int c = ch - 'a';
            if (c < 0 || c >= 26 || st[v].next[c] == -1) return false;
            v = st[v].next[c];
        }
        return true;
    }

    void propagateOccurrences() {
        vector<int> order(st.size());
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) { return st[a].len < st[b].len; });
        for (int i = static_cast<int>(order.size()) - 1; i > 0; --i) {
            int v = order[i];
            st[st[v].link].occ += st[v].occ;
        }
    }
};

