        }
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    }

    int kth(int node, int l, int r, int k) const {
        if (l == r) return l;
        int mid = l + (r - l) / 2;
        int leftCount = tree[node * 2];
        if (k <= leftCount) return kth(node * 2, l, mid, k);
        return kth(node * 2 + 1, mid + 1, r, k - leftCount);
    }

   public:
