        int mid = l + (r - l) / 2;
        push(node);
        rangeChmin(node * 2, l, mid, ql, qr, x);
        rangeChmin(node * 2 + 1, mid + 1, r, ql, qr, x);
        tree[node] = merge(tree[node * 2], tree[node * 2 + 1]);
