class FordFulkerson {
    vector<vector<int>> adj;
    vector<vector<long long>> capacity;
    vector<int> visited;

    long long dfs(int u, int t, long long flow) {
        if (u == t) return flow;
        visited[u] = 1;
        for (int v : adj[u]) {
            if (visited[v] || capacity[u][v] == 0) continue;
            long long pushed = dfs(v, t, min(flow, capacity[u][v]));
            if (pushed == 0) continue;
            capacity[u][v] -= pushed;
            capacity[v][u] += pushed;
            return pushed;
        }
        return 0;
    }

   public:
    explicit FordFulkerson(int n) : adj(n), capacity(n, vector<long long>(n, 0)), visited(n, 0) {}

    void addEdge(int u, int v, long long cap) {
        if (capacity[u][v] == 0 && capacity[v][u] == 0) {
            adj[u].push_back(v);
            adj[v].push_back(u);
        }
        capacity[u][v] += cap;
    }

    long long maxFlow(int s, int t) {
        long long flow = 0;
        while (true) {
            fill(visited.begin(), visited.end(), 0);
            long long pushed = dfs(s, t, LLONG_MAX);
            if (pushed == 0) break;
            flow += pushed;
        }
        return flow;
    }
};

