vector<long long> generateSubsetSums(const vector<long long>& arr, int l, int r) {
    int len = r - l;
    size_t total = 1ULL << len;
    vector<long long> sums;
    sums.reserve(total);
    for (size_t mask = 0; mask < total; ++mask) {
        long long sum = 0;
        for (int i = 0; i < len; ++i) {
            if (mask & (1ULL << i)) sum += arr[l + i];
        }
        sums.push_back(sum);
    }
    return sums;
}

bool subsetSumMITM(vector<long long>& arr, long long target) {
    int n = arr.size();
    int mid = n / 2;
    vector<long long> left, right;
    int n1 = mid;
    int n2 = n - mid;
    for (int mask = 0; mask < (1 << n1); mask++) {
        long long sum = 0;
        for (int i = 0; i < n1; i++) {
            if (mask & (1 << i)) sum += arr[i];
        }
        left.push_back(sum);
    }
    for (int mask = 0; mask < (1 << n2); mask++) {
        long long sum = 0;
        for (int i = 0; i < n2; i++) {
            if (mask & (1 << i)) sum += arr[mid + i];
        }
        right.push_back(sum);
    }
    sort(right.begin(), right.end());
    for (long long x : left) {
        long long need = target - x;
        if (binary_search(right.begin(), right.end(), need)) return true;
    }
    return false;
}

vector<long long> generateSubsetSums(const vector<long long>& arr, int l, int r) {
    int len = r - l;
    size_t total = 1ULL << len;
    vector<long long> sums;
