}

long long closestSubsetSum(const vector<long long>& arr, long long target) {
    int n = static_cast<int>(arr.size());
    int mid = n / 2;
    vector<long long> left = generateSubsetSums(arr, 0, mid);
    vector<long long> right = generateSubsetSums(arr, mid, n);
    sort(right.begin(), right.end());

    long long bestSum = 0;
    long long bestDiff = LLONG_MAX;
    auto relax = [&](long long candidate) {
        long long diff = llabs(candidate - target);
        if (diff < bestDiff || (diff == bestDiff && candidate < bestSum)) {
            bestDiff = diff;
            bestSum = candidate;
        }
    };

    for (long long x : left) {
        long long need = target - x;
        auto it = lower_bound(right.begin(), right.end(), need);
        if (it != right.end()) relax(x + *it);
        if (it != right.begin()) {
            --it;
            relax(x + *it);
        }
    }
    return bestSum;
}

long long countSubsetsLE(vector<long long>& arr, long long X) {
    int n = arr.size();
    int mid = n / 2;
    vector<long long> left, right;
    for (int mask = 0; mask < (1 << mid); mask++) {
        long long sum = 0;
        for (int i = 0; i < mid; i++)
            if (mask & (1 << i)) sum += arr[i];
        left.push_back(sum);
    }
    int rightN = n - mid;
    for (int mask = 0; mask < (1 << rightN); mask++) {
        long long sum = 0;
        for (int i = 0; i < rightN; i++)
            if (mask & (1 << i)) sum += arr[mid + i];
        right.push_back(sum);
    }
    sort(right.begin(), right.end());
    long long ans = 0;
    for (long long x : left) {
        long long limit = X - x;
        ans += upper_bound(right.begin(), right.end(), limit) - right.begin();
    }
    return ans;
}

long long countSubsetSum(vector<long long>& arr, long long X) {
    int n = arr.size();
    int mid = n / 2;
    unordered_map<long long, long long> freq;
    for (int mask = 0; mask < (1 << mid); mask++) {
        long long sum = 0;
        for (int i = 0; i < mid; i++)
            if (mask & (1 << i)) sum += arr[i];
        freq[sum]++;
    }
    long long ans = 0;
    int rightN = n - mid;
    for (int mask = 0; mask < (1 << rightN); mask++) {
        long long sum = 0;
        for (int i = 0; i < rightN; i++)
            if (mask & (1 << i)) sum += arr[mid + i];
        ans += freq[X - sum];
    }
    return ans;
}

bool fourSumMITM(vector<int>& arr, int target) {
    int n = arr.size();
    unordered_map<long long, vector<pair<int, int>>> mp;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            mp[(long long)arr[i] + arr[j]].push_back({i, j});
        }
    }
    for (auto& [sum, pairs] : mp) {
        long long need = (long long)target - sum;
        if (!mp.count(need)) continue;
        for (auto [i, j] : pairs) {
            for (auto [x, y] : mp[need]) {
                if (i != x && i != y && j != x && j != y) return true;
            }
        }
    }
    return false;
}

long long maxSubsetSum(vector<long long>& arr, long long K) {
    int n = arr.size();
    int mid = n / 2;
    vector<long long> left, right;
    for (int mask = 0; mask < (1 << mid); mask++) {
        long long sum = 0;
        for (int i = 0; i < mid; i++)
            if (mask & (1 << i)) sum += arr[i];
        if (sum <= K) left.push_back(sum);
    }
    int rightN = n - mid;
    for (int mask = 0; mask < (1 << rightN); mask++) {
        long long sum = 0;
        for (int i = 0; i < rightN; i++)
            if (mask & (1 << i)) sum += arr[mid + i];
        if (sum <= K) right.push_back(sum);
    }
    sort(right.begin(), right.end());
    long long ans = 0;
    for (long long x : left) {
        long long need = K - x;
        auto it = upper_bound(right.begin(), right.end(), need);
        if (it != right.begin()) {
            --it;
            ans = max(ans, x + *it);
        }
    }
    return ans;
}

long long minimumDifference(vector<long long>& arr) {
    int n = arr.size();
    int mid = n / 2;
    long long total = accumulate(arr.begin(), arr.end(), 0LL);
    vector<long long> left, right;
    for (int mask = 0; mask < (1 << mid); mask++) {
        long long sum = 0;
        for (int i = 0; i < mid; i++)
            if (mask & (1 << i)) sum += arr[i];
        left.push_back(sum);
    }
    int rightN = n - mid;
    for (int mask = 0; mask < (1 << rightN); mask++) {
        long long sum = 0;
        for (int i = 0; i < rightN; i++)
            if (mask & (1 << i)) sum += arr[mid + i];
        right.push_back(sum);
    }
    sort(right.begin(), right.end());
    long long ans = LLONG_MAX;
    for (long long x : left) {
        long long need = total / 2 - x;
        auto it = lower_bound(right.begin(), right.end(), need);
        if (it != right.end()) {
            long long subset = x + *it;
            ans = min(ans, abs(total - 2 * subset));
        }
        if (it != right.begin()) {
            --it;
            long long subset = x + *it;
            ans = min(ans, abs(total - 2 * subset));
        }
    }
    return ans;
}

long long minimumEqualPartition(vector<int>& arr) {
    int n = arr.size();
    int half = n / 2;
    vector<vector<long long>> left(half + 1);
    vector<vector<long long>> right(half + 1);
    for (int mask = 0; mask < (1 << half); mask++) {
        long long sum = 0;
        int cnt = 0;
        for (int i = 0; i < half; i++) {
            if (mask & (1 << i)) {
                sum += arr[i];
                cnt++;
            }
        }
        left[cnt].push_back(sum);
    }
    for (int mask = 0; mask < (1 << half); mask++) {
        long long sum = 0;
        int cnt = 0;
        for (int i = 0; i < half; i++) {
            if (mask & (1 << i)) {
                sum += arr[half + i];
                cnt++;
            }
        }
        right[cnt].push_back(sum);
    }
    for (auto& v : right) sort(v.begin(), v.end());
    long long total = accumulate(arr.begin(), arr.end(), 0LL);
    long long ans = LLONG_MAX;
    for (int cnt = 0; cnt <= half; cnt++) {
        int need = half - cnt;
        for (long long x : left[cnt]) {
            long long target = total / 2 - x;
            auto it = lower_bound(right[need].begin(), right[need].end(), target);
            if (it != right[need].end()) {
                long long selected = x + *it;
                ans = min(ans, abs(total - 2 * selected));
            }
            if (it != right[need].begin()) {
                --it;
                long long selected = x + *it;
                ans = min(ans, abs(total - 2 * selected));
            }
        }
    }
    return ans;
}

long long maximizeCoveredValue(const vector<long long>& values, const vector<int>& masks, int constraintCount) {
    int n = static_cast<int>(values.size());
    if (masks.size() != values.size() || constraintCount < 0 || constraintCount > 20) {
        return LLONG_MIN;
    }

    int mid = n / 2;
    vector<pair<int, long long>> left, right;

    for (int subset = 0; subset < (1 << mid); ++subset) {
        int mask = 0;
        long long value = 0;
        for (int i = 0; i < mid; ++i) {
            if (subset & (1 << i)) {
                mask |= masks[i];
                value += values[i];
            }
        }
        left.push_back({mask, value});
    }

    int rightSize = n - mid;
    for (int subset = 0; subset < (1 << rightSize); ++subset) {
        int mask = 0;
        long long value = 0;
        for (int i = 0; i < rightSize; ++i) {
            if (subset & (1 << i)) {
                mask |= masks[mid + i];
                value += values[mid + i];
            }
        }
        right.push_back({mask, value});
    }

    int fullMask = (1 << constraintCount) - 1;
    vector<long long> best(1 << constraintCount, LLONG_MIN);
    for (auto [mask, value] : right) {
        best[mask] = max(best[mask], value);
    }
    for (int bit = 0; bit < constraintCount; ++bit) {
        for (int mask = 0; mask <= fullMask; ++mask) {
            if ((mask & (1 << bit)) == 0) {
                best[mask] = max(best[mask], best[mask | (1 << bit)]);
            }
        }
    }

    long long ans = LLONG_MIN;
    for (auto [mask, value] : left) {
        int need = fullMask ^ mask;
        if (best[need] == LLONG_MIN) continue;
        ans = max(ans, value + best[need]);
    }
    return ans;
}

bool subsetXOR(vector<int>& arr, int X) {
    int n = arr.size();
    int mid = n / 2;
    unordered_set<int> left;
    for (int mask = 0; mask < (1 << mid); mask++) {
        int x = 0;
        for (int i = 0; i < mid; i++)
            if (mask & (1 << i)) x ^= arr[i];
        left.insert(x);
    }
    int rightN = n - mid;
    for (int mask = 0; mask < (1 << rightN); mask++) {
        int x = 0;
        for (int i = 0; i < rightN; i++)
            if (mask & (1 << i)) x ^= arr[mid + i];
        if (left.count(X ^ x)) return true;
    }
    return false;
}

