class Remote {
public:
    void submit(std::unique_ptr<Command> command) {
        // The request is an object, so it can be stored and undone later.
        command->execute();
        history_.push_back(std::move(command));
    }

    void undoLast() {
        if (!history_.empty()) {
            history_.back()->undo();
            history_.pop_back();
        }
    }

private:
    std::vector<std::unique_ptr<Command>> history_;
};

