class DataExporter {
public:
    virtual ~DataExporter() = default;

    void exportData() const {
        // The base class fixes the algorithm skeleton; subclasses fill selected steps.
        connect();
        writeHeader();
        writeRows();
        disconnect();
    }

protected:
    void connect() const { std::cout << "Connect\n"; }
