class VendingMachine {
    unordered_map<int, Slot*> slots;
    double money = 0;
public:
    void addProduct(int slotId, Slot* slot) {
        slots[slotId] = slot;
    }
    void insertMoney(double amount) {
        money += amount;
    }
    void selectProduct(int slotId) {
        if (!slots.count(slotId)) {
            cout << "Invalid slot\n";
            return;
        }
        Slot* slot = slots[slotId];
        if (!slot->isAvailable()) {
            cout << "Out of stock\n";
            return;
        }
        Product* product = slot->getProduct();
        if (money < product->getPrice()) {
            cout << "Insufficient money\n";
            return;
        }
        double change = money - product->getPrice();
        slot->removeProduct();
        cout << "Dispensing "
