class Inventory {
    unordered_map<string, int> ingredients;
public:
    void add(string ingredient, int quantity) {
        ingredients[ingredient] += quantity;
    }
    bool has(string ingredient, int quantity) {
        return ingredients[ingredient] >= quantity;
    }
    void consume(string ingredient, int quantity) {
        ingredients[ingredient] -= quantity;
    }
};

class Recipe {
    unordered_map<string, int> ingredients;
public:
    void addIngredient(string name, int quantity) {
        ingredients[name] = quantity;
    }
    bool canPrepare(Inventory& inventory) {
        for (auto &[name, quantity] : ingredients) {
            if (!inventory.has(name, quantity))
                return false;
        }
        return true;
    }
    void consume(Inventory& inventory) {
        for (auto &[name, quantity] : ingredients)
            inventory.consume(name, quantity);
    }
};

class CoffeeMachine {
