    void prepare(BeverageType type, double money) {
        Recipe& recipe = recipes[type];
        if (!recipe.canPrepare(inventory)) {
            cout << "Ingredients unavailable\n";
            return;
        }
        // Assume price lookup/payment validation here
        recipe.consume(inventory);
        cout << "Coffee prepared\n";
    }
};

