class LogAppender {
public:
    virtual void append(
        LogLevel level,
        string message
    ) = 0;
    virtual ~LogAppender() {}
};

class ConsoleAppender : public LogAppender {
public:
    void append(
        LogLevel level,
        string message
    ) override {
        cout << message << "\n";
    }
};

class FileAppender : public LogAppender {
public:
    void append(
        LogLevel level,
        string message
    ) override {
        ofstream file("app.log", ios::app);
        file << message << "\n";
    }
};

class Logger {
    LogLevel minLevel;
    vector<LogAppender*> appenders;
    Logger() {
        minLevel = LogLevel::DEBUG;
    }
public:
    static Logger& getInstance() {
        static Logger logger;
        return logger;
    }
    void setLevel(LogLevel level) {
        minLevel = level;
    }
    void addAppender(LogAppender* appender) {
        appenders.push_back(appender);
    }
    void log(
        LogLevel level,
        string message
    ) {
        if (level < minLevel)
            return;
        for (auto appender : appenders)
            appender->append(level, message);
    }
};

int main() {
    Logger& logger = Logger::getInstance();
    ConsoleAppender console;
    FileAppender file;
    logger.addAppender(&console);
    logger.addAppender(&file);
    logger.log(
        LogLevel::INFO,
        "Server started"
    );
    logger.log(
        LogLevel::ERROR,
        "Database connection failed"
    );
}

