        rooms.push_back(room);
    }
    Booking* bookRoom(
        User* user,
        TimeSlot slot,
        int requiredCapacity
    ) {
        for (auto room : rooms) {
            if (room->getCapacity() < requiredCapacity)
                continue;
            if (!room->isAvailable(slot))
                continue;
            Booking* booking =
                new Booking(
                    bookingId++,
                    user,
                    room,
                    slot
                );
            room->addBooking(booking);
            return booking;
        }
        return nullptr;
    }
