class EvictionPolicy {
public:
    virtual void keyAccessed(int key) = 0;
    virtual int evict() = 0;
    virtual ~EvictionPolicy() {}
};

class LRUPolicy : public EvictionPolicy {
    list<int> keys;
    unordered_map<
        int,
        list<int>::iterator
    > position;
public:
    void keyAccessed(int key) override {
        if (position.count(key))
            keys.erase(position[key]);
        keys.push_front(key);
        position[key] = keys.begin();
    }
    int evict() override {
        int key = keys.back();
        keys.pop_back();
        position.erase(key);
        return key;
    }
};

class Cache {
    int capacity;
    unordered_map<int, int> data;
    EvictionPolicy* policy;
public:
    Cache(
        int capacity,
        EvictionPolicy* policy
    ) : capacity(capacity),
        policy(policy) {}
    int get(int key) {
        if (!data.count(key))
            return -1;
        policy->keyAccessed(key);
        return data[key];
    }
    void put(int key, int value) {
        if (data.count(key)) {
            data[key] = value;
            policy->keyAccessed(key);
            return;
        }
        if (data.size() == capacity) {
            int keyToRemove =
                policy->evict();
            data.erase(keyToRemove);
        }
        data[key] = value;
        policy->keyAccessed(key);
    }
};

LRUPolicy policy;
Cache cache(3, &policy);
cache.put(1, 100);
cache.put(2, 200);
cache.put(3, 300);
cache.get(1);
cache.put(4, 400);

